}

#include <stdio.h>
int first_on_line(void)
{
    int first = getchar();
    if (first == EOF || first == '\n') return first;
    int tail;
    while ((tail = getchar()) != '\n' && tail != EOF) {}
    return first;
}
int count_task(void)
{
    int count;
    printf("count 0..4\n");
    int status = scanf("%d", &count);
    if (status == EOF) return 0;
    int tail;
    while ((tail = getchar()) != '\n' && tail != EOF) {}
    if (status != 1 || count < 0 || count > 4) printf("invalid count\n");
    else for (int i = 1; i <= count; i++) printf("%d\n", i);
    return 1;
}
int main(void)
{
    for (;;) {
        printf("a:help c:count q:quit\n");
        int choice = first_on_line();
        if (choice == EOF || choice == 'q') break;
        if (choice == 'a') printf("help\n");
        else if (choice == 'c') {
            if (!count_task()) break;
        } else printf("invalid choice\n");
    }
    printf("bye\n");
    return 0;
}

nodes.body:
# 第9章 函数

函数把一个程序拆成有明确接口的任务。调用者给出实参，被调函数在自己的局部对象中完成工作，再通过返回值或明确的副作用把结果交出去。本章先把声明、定义和调用联系起来，再讨论递归、多文件组织与指针通信。

### 声明接口、调用函数、提供定义（完整C程序）

```c
#include <stdio.h>
void rule(void);
int main(void)
{
    rule();
    printf("Course\n");
    rule();
    return 0;
}
void rule(void)
{
    for (int count = 0; count < 6; count++) putchar('*');
    putchar('\n');
}
```

**输入**：无需输入。

**真实C6运行结果**：

```text
******
Course
******
```

同一个rule被调用两次，每次都打印六个星号与换行；它不需要参数，也不返回一个供调用者使用的值。main只需知道这份约定，就能把两次调用放在标题前后。

把代码放进函数并非只为少写几行。接口让调用者明确依赖哪些行为，也让实现能够单独修改；前提是函数名称、输入要求、返回意义和可能的副作用保持一致。后续例子会逐步改变这些通信方式，观察调用者能看到哪些结果。

# 9.1 复习函数

一个函数可以计算并返回值，也可以执行输出或改变获准访问的对象，还可能同时做这些事。把功能划分成函数时，应先确定调用者需要什么，再选择传入参数、返回值和副作用。

### 声明接口、调用函数、提供定义（完整C程序）

```c
#include <stdio.h>
void rule(void);
int main(void)
{
    rule();
    printf("Course\n");
    rule();
    return 0;
}
void rule(void)
{
    for (int count = 0; count < 6; count++) putchar('*');
    putchar('\n');
}
```

**输入**：无需输入。

**真实C6运行结果**：

```text
******
Course
******
```

rule承担“输出一条分隔线”，main负责标题的整体顺序。rule里的计数器只服务本次调用，不必交给main管理；如果宽度也要由调用者决定，就应把宽度变成接口中的参数，而不是让main偷偷依赖某个局部变量。

函数并不需要重复调用多次才值得存在。一次性的复杂任务也能通过合理拆分变得清楚。反过来，把每个普通赋值都拆成函数，也未必改善理解；边界应该对应一项可说明、可检查的工作。

# 9.1.1 创建并使用简单函数

创建一个可调用函数，需要给出它的接口和实际函数体；调用则发生在程序需要完成这项工作的地方。原型结尾是分号，定义的参数列表后面接函数体，两者不能混写。

### 声明接口、调用函数、提供定义（完整C程序）

```c
#include <stdio.h>
void rule(void);
int main(void)
{
    rule();
    printf("Course\n");
    rule();
    return 0;
}
void rule(void)
{
    for (int count = 0; count < 6; count++) putchar('*');
    putchar('\n');
}
```

**输入**：无需输入。

**真实C6运行结果**：

```text
******
Course
******
```

前面的`void rule(void);`让main在看到定义前就知道调用方式。main中的`rule();`真正发起调用，文件后面的定义提供循环及输出。前一个void表示不返回值，参数位置的void表示没有形参。

执行从main进入rule，rule到函数体末尾后返回调用位置，main继续打印Course，随后再次调用rule。标准C不要求把所有定义都放在main之后；若完整定义已在第一次使用之前提供，也可以由该定义建立接口信息。

# 9.1.2 分析程序

分析含函数的程序，要分别看调用路径和对象归属。源码中出现相同函数名的多处位置，不代表每处都会执行函数体；原型只是声明，只有执行到调用时才进入相应工作。

### 声明接口、调用函数、提供定义（完整C程序）

```c
#include <stdio.h>
void rule(void);
int main(void)
{
    rule();
    printf("Course\n");
    rule();
    return 0;
}
void rule(void)
{
    for (int count = 0; count < 6; count++) putchar('*');
    putchar('\n');
}
```

**输入**：无需输入。

**真实C6运行结果**：

```text
******
Course
******
```

main按调用、标题、调用的顺序执行，rule的定义虽然写在文件后面，却在两次调用处都参与运行。每次进入rule，局部count重新从0开始，因此两条分隔线各有六个星号，而不是第二次沿用上次结束的6。

局部名称不直接暴露给其他函数，同名局部对象也可以各自存在。不过“不返回值”不等于“没有对外效果”：rule的标准输出明显可见。分析接口时应同时记录返回值和输出等副作用，不能只看是否写了return表达式。

# 9.1.3 函数参数

参数让一份实现处理不同数据。与把字符和次数固定在函数内部相比，调用者能通过接口选择两者，但函数仍按相同规则执行重复输出。

### 同一函数接收不同字符和次数（完整C程序）

```c
#include <stdio.h>
void repeat(int ch, int count);
int main(void)
{
    int padding = 2;
    repeat('#', 3);
    putchar('\n');
    repeat('.', padding);
    repeat('X', 3 - padding);
    putchar('\n');
    return 0;
}
void repeat(int ch, int count)
{
    for (int i = 0; i < count; i++) putchar(ch);
}
```

**输入**：无需输入。

**真实C6运行结果**：

```text
###
..X
```

三次调用分别给出常量、局部变量和表达式结果。repeat取得字符与次数，输出###、两个点和X；换行由main安排，所以两个调用的输出可以连接成同一行。

实参不必是变量，也不需要与形参同名。函数看到的是按接口转换后的值，而不是调用者书写表达式的文字。本例约定次数非负且字符适用于putchar；若希望负数报错、限制输出长度或处理输出失败，应把这些要求纳入接口，不能只靠函数名字暗示。

# 9.1.4 定义带形式参数的函数

形参在函数定义中声明，是本次调用的局部对象。每个形参都要给出自己的类型；不能沿用普通同类型对象声明的省略写法，把`int first, second`直接搬进参数列表。

### 形参是本次调用自己的对象（完整C程序）

```c
#include <stdio.h>
void advance(int count)
{
    count++;
    printf("inside=%d\n", count);
}
int main(void)
{
    int count = 3;
    advance(count);
    printf("caller=%d\n", count);
    return 0;
}
```

**输入**：无需输入。

**真实C6运行结果**：

```text
inside=4
caller=3
```

调用者count为3，advance的形参count由该值初始化，增加后打印inside=4；回到main，原对象仍打印caller=3。同名不表示同一对象，改成不同名称也不会改变传值规则。

这里改变的是标量副本，不是调用者对象。稍后传入指针时，指针值仍会复制，但可以通过这份地址值访问同一个所指对象。不要把本例概括成“函数内部永远不能影响外部数据”，否则就无法解释输出、全局对象或指针参数产生的作用。

# 9.1.5 声明带形式参数函数的原型

原型声明参数的数量和类型，让编译器能按接口检查调用；参数名在原型中可以省略，也可以为阅读者保留有意义的名字。它不在此刻创建供运行使用的形参对象。

### 同一函数接收不同字符和次数（完整C程序）

```c
#include <stdio.h>
void repeat(int ch, int count);
int main(void)
{
    int padding = 2;
    repeat('#', 3);
    putchar('\n');
    repeat('.', padding);
    repeat('X', 3 - padding);
    putchar('\n');
    return 0;
}
void repeat(int ch, int count)
{
    for (int i = 0; i < count; i++) putchar(ch);
}
```

**输入**：无需输入。

**真实C6运行结果**：

```text
###
..X
```

`void repeat(int ch, int count);`与省略名字的`void repeat(int, int);`表达相同参数类型。定义中再给出名字，函数体才能引用它们。原型名不必与定义中的形参名字相同，但返回类型和参数类型必须保持兼容。

调用两项不能因为类型相同就省成一个参数，交换位置也会改变含义：本例两个形参都是int，编译器无法替调用者识别“字符和次数颠倒”的业务错误。类型检查是必要帮助，接口说明与有代表性的调用仍然重要。

# 9.1.6 调用带实际参数的函数

实参是调用表达式中的表达式，调用时先取得其值，再按对应形参要求传入。调用者可以使用常量、对象当前值或计算结果，而被调函数使用本次形参对象完成工作。

### 同一函数接收不同字符和次数（完整C程序）

```c
#include <stdio.h>
void repeat(int ch, int count);
int main(void)
{
    int padding = 2;
    repeat('#', 3);
    putchar('\n');
    repeat('.', padding);
    repeat('X', 3 - padding);
    putchar('\n');
    return 0;
}
void repeat(int ch, int count)
{
    for (int i = 0; i < count; i++) putchar(ch);
}
```

**输入**：无需输入。

**真实C6运行结果**：

```text
###
..X
```

padding为2，所以第二次输出两个点，第三次的`3 - padding`先形成1，再让repeat输出一个X。repeat并不知道1原先来自一次减法，也不会因为自己的局部循环更新就修改padding。

多个实参的求值顺序一般不能假定从左到右。如果准备实参时需要先更新同一对象再使用它，应先用独立语句明确顺序，而不是把相互冲突的更新都塞在一次调用里。参数位置固定对应接口，与实参之间的实际求值时间顺序是两件事。

# 9.1.7 黑盒视角

黑盒视角是按接口使用函数：给定哪些输入，在什么前提下会得到哪些值或动作。它隐藏不必依赖的内部细节，而不是允许忽略对象有效性、失败条件和副作用。

### 返回值交给调用者使用（完整C程序）

```c
#include <stdio.h>
int minimum(int left, int right);
int main(void)
{
    int found = minimum(7, -2);
    printf("minimum=%d expression=%d\n", found, 2 * minimum(3, 5) + 1);
    return 0;
}
int minimum(int left, int right)
{
    if (left < right) return left;
    return right;
}
```

**输入**：无需输入。

**真实C6运行结果**：

```text
minimum=-2 expression=7
```

minimum的约定是接收两个int，返回其中较小者，参数相等时返回同样的值。调用者不需要知道实现用了if还是条件运算符；found取得-2，表达式调用取得3，组合结果为7。

函数的内部局部变量不会凭名称直接与调用者共享，但接口可能明确允许通过指针或全局状态产生作用。要替换实现，应保持约定的结果与相关副作用，而不只是让某一组打印文本相同。独立驱动程序应选择不同顺序、相等值和边界等有意义情况检验接口。

# 9.1.8 使用return从函数中返回值

return可以结束当前函数调用，并在有返回值的函数中把表达式结果交给调用者。调用者可保存这个值，也可把调用直接放进更大的表达式；它不能直接读取被调函数的局部对象名。

### 返回值交给调用者使用（完整C程序）

```c
#include <stdio.h>
int minimum(int left, int right);
int main(void)
{
    int found = minimum(7, -2);
    printf("minimum=%d expression=%d\n", found, 2 * minimum(3, 5) + 1);
    return 0;
}
int minimum(int left, int right)
{
    if (left < right) return left;
    return right;
}
```

**输入**：无需输入。

**真实C6运行结果**：

```text
minimum=-2 expression=7
```

两条return分别覆盖left较小和其余情况，执行一条后就离开minimum，不会继续走另一条。found保存返回的-2；第二次调用作为乘法的一部分使用，结果不必先放进一个专门中间变量。

### return结束当前调用，调用者仍继续（完整C程序）

```c
#include <stdio.h>
void report(int value)
{
    if (value < 0) {
        printf("invalid\n");
        return;
    }
    printf("value=%d\n", value);
}
int main(void)
{
    report(-1);
    report(4);
    printf("caller continues\n");
    return 0;
}
```

**输入**：无需输入。

**真实C6运行结果**：

```text
invalid
value=4
caller continues
```

void函数中的`return;`只结束当前report调用，main仍可再次调用并继续报告。沿当前执行路径，return之后不再继续本函数的后续语句；多个出口可以合理使用，但每条路径都应符合返回约定。非void普通函数若运行到末尾而调用者使用缺失的返回值，不能期待自动返回0；main到末尾的特殊规则不能推给所有函数。

# 9.1.9 函数类型

返回类型决定函数交给调用者的值类型，参数类型决定输入如何接收，两者可以不同。严格说，函数类型不仅是返回类型，还包含参数等接口信息；不能把“函数类型”完全缩成一个int或double名字。

### 返回表达式转换成声明的返回类型（完整C程序）

```c
#include <stdio.h>
int whole_part(int divisor)
{
    return 100.0 / divisor;
}
double fraction(int divisor)
{
    return 100.0 / divisor;
}
int main(void)
{
    printf("whole=%d fraction=%.4f\n", whole_part(64), fraction(64));
    return 0;
}
```

**输入**：无需输入。

**真实C6运行结果**：

```text
whole=1 fraction=1.5625
```

两个函数都计算100.0/64，数学结果为1.5625；whole_part声明返回int，因此返回时转换成1，fraction声明返回double，保留1.5625。改变返回声明会改变调用者拿到的值，不只是改变显示格式。

这里两次调用的除数都固定为64且结果可表示，转换安全。若浮点结果超出目标整数范围，不能照本例推断仍有某个可用截断结果。C99及本书采用的C11均不再允许省略返回类型后默认int，书中个别简写函数头在新代码中要补齐类型。

# 9.2 ANSI C函数原型

原型在调用点提供足够的参数信息，使接口检查和必要转换能够发生。它能发现许多调用错误，但不能证明业务含义、对象寿命和算法结果都正确。

### 原型让数值实参按形参类型转换（完整C程序）

```c
#include <stdio.h>
int maximum(int, int);
int main(void)
{
    printf("maximum=%d\n", maximum(3.9, 5.4));
    return 0;
}
int maximum(int first, int second)
{
    return first > second ? first : second;
}
```

**输入**：无需输入。

**真实C6运行结果**：

```text
maximum=5
```

maximum原型明确两个int，3.9与5.4在调用时转换成3与5，结果为5。参数类型不一样并不必然是错误；关键在于是否允许相应转换、转换后是否仍符合业务要求。这里输入结果都在int可表示范围中。

本书C11历史语境中的`int maximum();`没有提供参数数量和类型列表，与完整原型不同。新代码采用显式原型或在首次使用前提供完整定义，不靠旧式声明隐藏不一致，也不通过手写不正确的标准库声明绕开对应头文件。

# 9.2.1 问题所在

调用点缺少参数信息时，错误可能一直到运行才暴露；即使某个旧编译器允许生成程序，也不能把偶然输出当成语言规定。缺少一个参数不是自动补0，错误类型也不是自动按期待重新解释。

### 阅读C11旧式声明为何缺乏参数信息（完整标准C阅读程序）

C11历史语境的旧式声明与K&R形式定义不在C6闭合语法内。本例故意含错误调用，供分析接口风险，不应实际使用。

```c
#include <stdio.h>
int maximum();
int main(void)
{
    printf("%d\n", maximum(3));
    return 0;
}
int maximum(first, second)
int first, second;
{
    return first > second ? first : second;
}
```

**教学预期（非本平台实测）**：旧式maximum()声明未提供参数列表信息；本例只传一项而定义需要两项，行为未定义，没有正确输出或固定垃圾值可预测。不能从某编译器偶然输出推断ABI或缺省参数。

旧式声明没有向调用点提供所需的两个参数信息，本例故意只传一项。缺失参数导致行为未定义，不能给第二项指定一个“栈上的随机数”作为可预测答案；实际调用机制也不保证所有参数都放在某种固定布局的栈里。

### 参数缺少是接口错误（完整诊断示例）

```c
#include <stdio.h>
int maximum(int first, int second)
{
    return first > second ? first : second;
}
int main(void)
{
    printf("%d\n", maximum(3));
    return 0;
}
```

**输入**：无需输入。

**真实C6检查结果**：`E_ARGUMENTS`。maximum原型要求两个int参数，调用只给一项，C6拒绝执行；标准C也要求对此违反约束的调用给出诊断，不存在可承诺的第二参数值。

明确接口后的错误调用得到真实E_ARGUMENTS诊断，没有可用输出。本平台并未原生运行旧式程序来观察垃圾值；两段代码分别说明历史接口风险和当前受支持接口检查，不能把拒绝诊断说成已经复现某个宿主ABI。

# 9.2.2 ANSI的解决方案

原型把调用需要遵守的数量与类型写进声明。参数不足或不符合约束时需要诊断；对于允许的数值转换，调用者仍应考虑是否损失了业务需要的信息。

### 原型让数值实参按形参类型转换（完整C程序）

```c
#include <stdio.h>
int maximum(int, int);
int main(void)
{
    printf("maximum=%d\n", maximum(3.9, 5.4));
    return 0;
}
int maximum(int first, int second)
{
    return first > second ? first : second;
}
```

**输入**：无需输入。

**真实C6运行结果**：

```text
maximum=5
```

本次double实参转换为int，得到3和5，所以最大值为5。原型让函数接收到正确类型，不代表程序保留了原来的小数部分；若任务要比较3.9与5.4并返回较大的小数，就应改成相应的浮点接口。

编译器可以对潜在损失给出额外警告，具体级别和文字依实现设置而定。C所要求的诊断也不意味着所有实现都必须拒绝继续翻译，不能把“警告一定可运行、错误一定不可生成”当作跨实现语言规则。课堂判断依据应先是代码是否符合接口约束。

# 9.2.3 无参数和未指定参数

在本书讨论的C11声明语境中，空括号没有参数类型列表，而单独写void明确声明无形参。为了让无参数接口清楚，课程统一使用`function(void)`声明和定义，在调用时写空括号。

### void明确表示无形参（完整C程序）

```c
#include <stdio.h>
void ready(void);
int main(void)
{
    ready();
    return 0;
}
void ready(void)
{
    printf("ready\n");
}
```

**输入**：无需输入。

**真实C6运行结果**：

```text
ready
```

ready不需要实参，调用后只输出ready。声明处参数位置的void与返回类型的void分属两个位置：前者限制输入，后者说明没有返回值；不能因为都写void就把两个作用合并。

可变参数函数也不是“完全不检查参数”的同义词。printf有固定的首个参数，后接省略号部分；类型和数量还必须与格式约定匹配，默认参数提升不能替你修正错误格式。自定义可变参数将在后续预处理与库内容中阅读，当前C6不因此开放任意可变参数定义。

# 9.2.4 函数原型的优点

显式接口使调用错误更早可见，也让实现可以移动到别的文件。对于小函数，完整定义位于第一次使用之前时，同样能提供带类型的参数信息，不要求另外机械重复一份原型。

### 形参是本次调用自己的对象（完整C程序）

```c
#include <stdio.h>
void advance(int count)
{
    count++;
    printf("inside=%d\n", count);
}
int main(void)
{
    int count = 3;
    advance(count);
    printf("caller=%d\n", count);
    return 0;
}
```

**输入**：无需输入。

**真实C6运行结果**：

```text
inside=4
caller=3
```

advance定义先于main，调用时已经知道它接受int并且不返回值，因此没有单独的前置声明。局部形参的变化仍不影响main的count，接口位置不会改变传值规则。

把定义移到调用之后时，就要先提供兼容声明。把函数分到另一源文件时，更适合用公共头分享同一原型并让实现也包含它，以便发现双方不一致；不能只在调用文件临时猜一个签名。原型检查范围有限，语义上颠倒同类型参数仍需自行发现。

# 9.3 递归

递归是函数直接或间接再次调用自身。理解递归需要同时看基本情况、如何趋近基本情况，以及返回后还要做什么；只看到函数名再次出现还不足以判断它会终止。

### 递归进入顺序与返回顺序不同（完整C程序）

```c
#include <stdio.h>
void visit(int level)
{
    printf("enter=%d\n", level);
    if (level < 3) visit(level + 1);
    printf("leave=%d\n", level);
}
int main(void)
{
    visit(1);
    return 0;
}
```

**输入**：无需输入。

**真实C6运行结果**：

```text
enter=1
enter=2
enter=3
leave=3
leave=2
leave=1
```

visit从1逐级进入2和3，到3不再调用自己；随后按3、2、1的顺序报告leave。每一层都保留自己的level，内层到3并没有把外层形参也改成3。

返回会继续执行该层尚未完成的动作，不是重新从函数顶部执行，也不是直接越过所有外层回main。平台用调用帧与真实轨迹展示这些状态，层数仍受资源预算限制；达到上限是停止执行的保护，不能当作递归算法已经正确收敛。

# 9.3.1 演示递归

先用一个有明确上限的完整程序观察递归顺序。把一条报告放在递归前，另一条放在递归后，就能区分进入新调用与恢复旧调用两个阶段。

### 递归进入顺序与返回顺序不同（完整C程序）

```c
#include <stdio.h>
void visit(int level)
{
    printf("enter=%d\n", level);
    if (level < 3) visit(level + 1);
    printf("leave=%d\n", level);
}
int main(void)
{
    visit(1);
    return 0;
}
```

**输入**：无需输入。

**真实C6运行结果**：

```text
enter=1
enter=2
enter=3
leave=3
leave=2
leave=1
```

enter依次1、2、3，leave依次3、2、1。3这一层因为条件失败而不再调用，但仍执行自己的leave，然后返回2这一层的递归调用之后。外层从暂停位置继续，不再重复打印已经完成的enter。

每层普通自动局部对象属于相应调用，代码定义则没有为每一层复制一份新的源码。若还要打印标准C地址，应使用匹配的%p接口；不能照来源建议改用%u或%lu随意打印指针。平台地址即使显示出来，也是虚拟对象位置，不是宿主内存地址。

# 9.3.2 递归的基本原理

递归的关键不是“每次改一个数”，而是证明在允许输入内能到达基本情况，并且每层等待的后续操作都有意义。递归返回一层后，该层自己的状态仍然有效。

### 递归进入顺序与返回顺序不同（完整C程序）

```c
#include <stdio.h>
void visit(int level)
{
    printf("enter=%d\n", level);
    if (level < 3) visit(level + 1);
    printf("leave=%d\n", level);
}
int main(void)
{
    visit(1);
    return 0;
}
```

**输入**：无需输入。

**真实C6运行结果**：

```text
enter=1
enter=2
enter=3
leave=3
leave=2
leave=1
```

从1起每次level加1，条件只在小于3时再次调用，因此必然到3停止深入。进入顺序与返回顺序相反，是因为每层都要等被调层结束后，才能完成自己的leave，而不是系统把一张输出表倒着播放。

若把推进方向改为递减，这个入口与条件就不再保证终止；若不同入口允许负数或更大范围，也应重新审视前提。普通递归调用仍遵守函数接口、局部对象与返回规则。并非每个合法C调用都保证正常返回，例如非终止路径或终止整个程序的操作需要另作分析。

# 9.3.3 尾递归

尾递归要求递归调用的结果能直接作为当前调用的结果继续返回，调用结束后没有尚待完成的乘法等运算。不能只看递归表达式在源码里是否靠近函数末尾。

### 区分普通递归、尾递归和循环阶乘（完整C程序）

```c
#include <stdio.h>
int recursive_fact(int n)
{
    if (n == 0) return 1;
    return n * recursive_fact(n - 1); // 返回后还需乘法，因此不是尾递归。
}
int tail_fact(int n, int product)
{
    if (n == 0) return product;
    return tail_fact(n - 1, product * n);
}
int loop_fact(int n)
{
    int product = 1;
    while (n > 0) {
        product *= n;
        n--;
    }
    return product;
}
int main(void)
{
    int n;
    if (scanf("%d", &n) != 1 || n < 0 || n > 6) {
        printf("range 0..6\n");
        return 1;
    }
    printf("recursive=%d tail=%d loop=%d\n",
           recursive_fact(n), tail_fact(n, 1), loop_fact(n));
    return 0;
}
```

**输入**：

```text
5
```

**真实C6运行结果**：

```text
recursive=120 tail=120 loop=120
```

recursive_fact返回`n * recursive_fact(n - 1)`，内层返回后还要乘n，所以不是尾递归。tail_fact把累计乘积作为参数传给下一层，直接返回下一层结果，才具有这里要讨论的尾递归结构。loop_fact则显式维护同样的累计状态。

输入5时三者都为120，0时都为1，6时都为720，负数被驱动程序拒绝。这里限定0至6，int足以容纳结果，不能照搬教材long的0至12域。标准C不保证尾调用优化，当前C6也不因尾位置就省去真实调用帧；输出相同不是内存或速度已经相同的证据。浮点类型可容纳更大的量级，也不等于能精确表示任意大阶乘。

# 9.3.4 递归和倒序计算

整数除2得到剩余高位，余2得到最低位。若先打印余数再递归，就会先输出低位；要按通常书写顺序输出二进制，应先递归处理高位，返回后再输出本层余数。

### 先递归处理高位，再输出当前余数（完整C程序）

```c
#include <stdio.h>
void binary(int value)
{
    int remainder = value % 2;
    if (value >= 2) binary(value / 2);
    putchar(remainder == 0 ? '0' : '1');
}
int main(void)
{
    int value;
    if (scanf("%d", &value) != 1 || value < 0 || value > 255) return 1;
    binary(value);
    putchar('\n');
    return 0;
}
```

**输入**：

```text
9
```

**真实C6运行结果**：

```text
1001
```

9的余数依次为1、0、0、1，但调用先深入到最高位，返回时才打印，因此实际输出1001。0仍执行一次最终输出，得到0；8输出1000，末尾三个0不会被误丢掉。

函数只在value至少2时继续调用value/2，使非负值逐渐缩小。这里使用int并把输入限制为0至255，不声称执行了教材unsigned long版本。负整数的表示还涉及符号与位宽约定，不能直接把这个非负算法套过去；循环方案也可以用暂存余数或其他明确方法完成，不要求所有场合必须递归。

# 9.3.5 递归的优缺点

递归的表达可以贴近问题结构，但代价要区分总工作量和同时存活的状态。朴素斐波那契会反复求相同子问题，耗费很多调用，不等于所有调用都同时占着内存。

### 观察重复子问题与总调用次数（完整C程序）

```c
#include <stdio.h>
int calls = 0;
int fibonacci(int n)
{
    calls++;
    if (n <= 2) return 1;
    int left = fibonacci(n - 1);
    int right = fibonacci(n - 2);
    return left + right;
}
int main(void)
{
    int n;
    if (scanf("%d", &n) != 1 || n < 1 || n > 8) return 1;
    int value = fibonacci(n);
    printf("value=%d calls=%d\n", value, calls);
    return 0;
}
```

**输入**：

```text
6
```

**真实C6运行结果**：

```text
value=8 calls=15
```

输入6得到值8、总调用15；输入1直接命中基本情况，只调用一次。求6时，求5的分支里已经算过4，随后另一分支又算4，所以重复工作来自展开的调用树。

本例先完成left调用，再完成right调用，避免把实参或二元表达式的未指定求值顺序混进观察。朴素版本总调用量增长很快，而逐层深度是随n线性增长；教材把指数总创建量直接说成同时存活的指数内存，需要纠正。递归不必然难读或比循环慢，具体算法、实现和优化都重要；这个定义更适合说明重复子问题，扩大范围应改进算法而不是只提高预算。

# 9.4 编译多源代码文件的程序

