#include <stdio.h>
int main(void)
{
    char text[16];
    int written = sprintf(text, "id=%d", 7);
    if (written < 0) return 1;
    printf("text=%s written=%d\n", text, written);
    return 0;
}

#include <stdio.h>
int main(void)
{
    char text[6];
    int needed = snprintf(text, sizeof text, "%s", "course");
    if (needed < 0) return 1;
    printf("needed=%d truncated=%d text=%s\n", needed, (size_t)needed >= sizeof text, text);
    return 0;
}

#include <stdio.h>
#include <string.h>
int main(void)
{
    char text[] = "elm\noak";
    char *found = strchr(text, '\n');
    if (found == 0) return 1;
    int offset = (int)(found - text);
    *found = '\0';
    char *end = strchr(text, '\0');
    printf("text=%s offset=%d missing=%d terminator=%d\n",
           text, offset, strchr(text, 'z') == 0, (int)(end - text));
    return 0;
}

#include <stdio.h>
#include <string.h>
int main(void)
{
    char text[] = "elm-oak-elm";
    char *last = strrchr(text, 'e');
    char *member = strpbrk(text, "oa");
    char *part = strstr(text, "oak");
    if (last == NULL || member == NULL || part == NULL) return 1;
    printf("last=%d set=%d sub=%d empty=%d\n", (int)(last - text),
           (int)(member - text), (int)(part - text), strstr(text, "") == text);
    return 0;
}

#include <stdio.h>
#include <string.h>
void sort(const char *items[], int count)
{
    for (int top = 0; top < count - 1; top++) {
        int smallest = top;
        for (int seek = top + 1; seek < count; seek++)
            if (strcmp(items[seek], items[smallest]) < 0) smallest = seek;
        const char *saved = items[top];
        items[top] = items[smallest];
        items[smallest] = saved;
    }
}
int main(void)
{
    char words[3][8] = {"pear", "apple", "fig"};
    const char *view[3] = {words[0], words[1], words[2]};
    sort(view, 3);
    printf("view=%s %s %s\n", view[0], view[1], view[2]);
    printf("storage=%s %s %s\n", words[0], words[1], words[2]);
    return 0;
}

#include <stdio.h>
#include <ctype.h>
int main(void)
{
    char text[] = "Elm?!";
    int letters = 0;
    for (int i = 0; text[i] != '\0'; i++) {
        int code = text[i];
        if (code >= 0 && code < 128) {
            if (isalpha(code)) letters++;
            text[i] = (char)toupper(code);
        }
    }
    printf("%s letters=%d\n", text, letters);
    return 0;
}

#include <stdio.h>
#include <ctype.h>
int main(void)
{
    char text[] = "Elm?!";
    int marks = 0;
    for (int i = 0; text[i] != '\0'; i++) {
        unsigned char code = (unsigned char)text[i];
        if (ispunct(code)) marks++;
        text[i] = (char)toupper(code);
    }
    printf("%s marks=%d\n", text, marks);
    return 0;
}

#include <stdio.h>
int main(int argc, char *argv[])
{
    for (int i = 1; i < argc; i++) printf("arg%d=%s\n", i, argv[i]);
    printf("sentinel=%d\n", argv[argc] == NULL);
    return 0;
}

#include <stdio.h>
#include <string.h>
int main(void)
{
    char response[8];
    while (scanf("%7s", response) == 1) {
        if (strcmp(response, "elm") == 0) {
            puts("accepted");
            return 0;
        }
        puts("retry");
    }
    puts("input ended");
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <errno.h>
#include <ctype.h>
void inspect(const char *text)
{
    char *end;
    errno = 0;
    long value = strtol(text, &end, 10);
    if (end == text || errno == ERANGE) {
        puts("invalid");
        return;
    }
    while (isspace((unsigned char)*end)) end++;
    if (*end != '\0' || value < 0 || value > 100) {
        puts("invalid");
        return;
    }
    printf("accepted=%ld\n", value);
}
int main(void)
{
    inspect("17");
    inspect("x");
    inspect("17x");
    inspect("999999999999999999999999999999");
    return 0;
}

