{
    int *copy = malloc(3 * sizeof *copy);
    if (copy == NULL) {
        puts("no memory");
        return;
    }
    int sum = 0;
    for (int i = 0; i < 3; ++i) {
        copy[i] = source[i];
        sum += copy[i];
    }
    printf("sum=%d\n", sum);
