#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
int main(int argc, char *argv[])
{
    if (argc != 2) {
        fputs("usage: count input-file\n", stderr);
        return EXIT_FAILURE;
    }
    FILE *input = fopen(argv[1], "rb");
    if (input == NULL) {
        fputs("cannot open input\n", stderr);
        return EXIT_FAILURE;
    }
    int status = EXIT_SUCCESS;
    size_t count = 0;
    int ch;
    while ((ch = getc(input)) != EOF) { // int同时保留读取字符和EOF两类结果。
        if (count == SIZE_MAX || putc(ch, stdout) == EOF) {
            status = EXIT_FAILURE;
            break;
        }
        ++count;
    }
    if (ferror(input)) status = EXIT_FAILURE;
    if (fclose(input) != 0) status = EXIT_FAILURE;
    if (status == EXIT_SUCCESS && printf("bytes=%zu\n", count) < 0)
        status = EXIT_FAILURE;
    if (fflush(stdout) == EOF) status = EXIT_FAILURE;
    return status;
}

