int main(void)
{
    FILE *file = tmpfile();
    if (file == NULL) return EXIT_FAILURE;
    int failed = fputs("abcde\nz\n", file) == EOF;
    if (!failed && fseek(file, 0L, SEEK_SET) != 0) failed = 1;
    char piece[4];
    if (!failed) {
        while (fgets(piece, sizeof piece, file) != NULL) {
            if (fputs(piece, stdout) == EOF) {
                failed = 1;
                break;
            }
        }
        if (ferror(file)) failed = 1;
    }
    if (fclose(file) != 0) failed = 1;
    if (fflush(stdout) == EOF) failed = 1;
    return failed ? EXIT_FAILURE : EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
int main(void)
{
    FILE *file = tmpfile();
    if (file == NULL) return EXIT_FAILURE;
    int failed = fputs("abcd", file) == EOF;
    if (!failed && fseek(file, 2L, SEEK_SET) != 0) failed = 1;
    if (!failed) {
        long position = ftell(file);
        int ch = getc(file);
        if (position == -1L || ch == EOF) failed = 1;
        else if (printf("position=%ld next=%c\n", position, ch) < 0) failed = 1;
    }
    if (fclose(file) != 0) failed = 1;
    return failed ? EXIT_FAILURE : EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
int main(int argc, char *argv[])
{
    if (argc != 2) return EXIT_FAILURE;
    FILE *file = fopen(argv[1], "r");
    if (file == NULL) return EXIT_FAILURE;
    int failed = 0;
    int first = getc(file);
    long mark = ftell(file);
    int second = getc(file);
    if (first == EOF || mark == -1L || second == EOF) failed = 1;
    if (!failed && fseek(file, mark, SEEK_SET) != 0) failed = 1;
    if (!failed) {
        int again = getc(file);
        if (again == EOF) failed = 1;
        else if (printf("first=%c second=%c again=%c same=%d\n",
                        first, second, again, second == again) < 0) failed = 1;
    }
    if (fclose(file) != 0) failed = 1;
    return failed ? EXIT_FAILURE : EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
int main(void)
{
    FILE *file = tmpfile();
    if (file == NULL) return EXIT_FAILURE;
    int failed = fputs("abc", file) == EOF;
    if (!failed && fseek(file, 0L, SEEK_SET) != 0) failed = 1;
    fpos_t mark;
    if (!failed && getc(file) != 'a') failed = 1;
    if (!failed && fgetpos(file, &mark) != 0) failed = 1;
    int second = EOF;
    if (!failed) second = getc(file);
    if (second == EOF) failed = 1;
    if (!failed && fsetpos(file, &mark) != 0) failed = 1;
    if (!failed) {
        int again = getc(file);
        if (again == EOF) failed = 1;
        else if (printf("same=%d\n", second == again) < 0) failed = 1;
    }
    if (fclose(file) != 0) failed = 1;
    return failed ? EXIT_FAILURE : EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
int main(void)
{
    FILE *file = tmpfile();
    if (file == NULL) return EXIT_FAILURE;
    int failed = fputs("ab", file) == EOF;
    if (!failed && fseek(file, 0L, SEEK_SET) != 0) failed = 1;
    if (!failed) {
        int first = getc(file);
        if (first == EOF || ungetc('X', file) == EOF) failed = 1;
        if (!failed) {
            int again = getc(file);
            int last = getc(file);
            if (again == EOF || last == EOF) failed = 1;
            else if (printf("%c%c%c\n", first, again, last) < 0) failed = 1;
        }
    }
    if (fclose(file) != 0) failed = 1;
    return failed ? EXIT_FAILURE : EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
int main(void)
{
    if (fputs("character? ", stdout) == EOF) return EXIT_FAILURE;
    if (fflush(stdout) == EOF) return EXIT_FAILURE; // 刷新输出，不用fflush(stdin)清输入。
    int ch = getchar();
    if (ch == EOF) return EXIT_FAILURE;
    if (printf("read=%c\n", ch) < 0) return EXIT_FAILURE;
    return fflush(stdout) == EOF ? EXIT_FAILURE : EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
int main(void)
{
    char buffer[128];
    FILE *file = tmpfile();
    if (file == NULL) return EXIT_FAILURE;
    if (setvbuf(file, buffer, _IOFBF, sizeof buffer) != 0) {
        fclose(file);
        return EXIT_FAILURE;
    }
    int failed = fputs("ab", file) == EOF;
    if (!failed && fflush(file) == EOF) failed = 1;
    if (!failed && fseek(file, 0L, SEEK_SET) != 0) failed = 1;
    if (!failed) {
        int ch = getc(file);
        if (ch == EOF || printf("%c\n", ch) < 0) failed = 1;
    }
    if (fclose(file) != 0) failed = 1;
    return failed ? EXIT_FAILURE : EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
int main(void)
{
    int values[3] = {7, 12, 19};
    int restored[3];
    FILE *file = tmpfile();
    if (file == NULL) return EXIT_FAILURE;
    int failed = fwrite(values, sizeof values[0], 3, file) != 3;
    if (!failed && fseek(file, 0L, SEEK_SET) != 0) failed = 1;
    if (!failed && fread(restored, sizeof restored[0], 3, file) != 3) failed = 1;
    if (!failed && printf("sum=%d\n", restored[0] + restored[1] + restored[2]) < 0)
        failed = 1;
    if (fclose(file) != 0) failed = 1;
    return failed ? EXIT_FAILURE : EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
int main(void)
{
    unsigned char data[3] = {0, 1, 255};
    FILE *file = tmpfile();
    if (file == NULL) return EXIT_FAILURE;
    size_t written = fwrite(data, sizeof data[0], 3, file);
    int failed = written != 3;
    if (printf("written=%zu\n", written) < 0) failed = 1;
    if (fclose(file) != 0) failed = 1;
    return failed ? EXIT_FAILURE : EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
int main(void)
{
    unsigned char source[2] = {3, 5};
    unsigned char data[4];
    FILE *file = tmpfile();
    if (file == NULL) return EXIT_FAILURE;
    int failed = fwrite(source, 1, 2, file) != 2;
    if (!failed && fseek(file, 0L, SEEK_SET) != 0) failed = 1;
    if (!failed) {
        size_t got = fread(data, 1, 4, file);
        int sum = 0;
        for (size_t i = 0; i < got; ++i) sum += data[i];
        if (printf("got=%zu sum=%d eof=%d error=%d\n", got, sum,
                   feof(file) != 0, ferror(file) != 0) < 0) failed = 1;
        if (ferror(file)) failed = 1;
    }
    if (fclose(file) != 0) failed = 1;
    return failed ? EXIT_FAILURE : EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
int main(void)
{
    FILE *file = tmpfile();
    if (file == NULL) return EXIT_FAILURE;
    int ch = getc(file);
    int failed = printf("stopped=%d eof=%d error=%d\n", ch == EOF,
                        feof(file) != 0, ferror(file) != 0) < 0;
    if (ferror(file)) failed = 1;
    clearerr(file);
    if (printf("after-clear eof=%d error=%d\n",
               feof(file) != 0, ferror(file) != 0) < 0) failed = 1;
    if (fclose(file) != 0) failed = 1;
    return failed ? EXIT_FAILURE : EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
int append_stream(FILE *source, FILE *target)
{
    unsigned char block[16];
    size_t got;
    while ((got = fread(block, 1, sizeof block, source)) > 0) {
        if (fwrite(block, 1, got, target) != got) return 0;
    }
    return !ferror(source);
}
int main(void)
{
    FILE *source = tmpfile();
    if (source == NULL) return EXIT_FAILURE;
    FILE *target = tmpfile();
    if (target == NULL) {
        fclose(source);
        return EXIT_FAILURE;
    }
    int failed = fputs("new\n", source) == EOF;
    if (fputs("old\n", target) == EOF) failed = 1;
    if (!failed && fseek(source, 0L, SEEK_SET) != 0) failed = 1;
    if (!failed && !append_stream(source, target)) failed = 1;
    if (!failed && fseek(target, 0L, SEEK_SET) != 0) failed = 1;
    if (!failed) {
        int ch;
        while ((ch = getc(target)) != EOF) {
            if (putchar(ch) == EOF) {
                failed = 1;
                break;
            }
        }
        if (ferror(target)) failed = 1;
    }
    if (fclose(source) != 0) failed = 1;
    if (fclose(target) != 0) failed = 1;
    if (fflush(stdout) == EOF) failed = 1;
    return failed ? EXIT_FAILURE : EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <limits.h>
int main(void)
{
    double values[3] = {1.5, 2.5, 3.5};
    if (sizeof values[0] > (unsigned long)LONG_MAX / 2) return EXIT_FAILURE;
    FILE *file = tmpfile();
    if (file == NULL) return EXIT_FAILURE;
    int failed = fwrite(values, sizeof values[0], 3, file) != 3;
    long offset = 2L * (long)sizeof values[0];
    if (!failed && fseek(file, offset, SEEK_SET) != 0) failed = 1;
    double value;
    if (!failed && fread(&value, sizeof value, 1, file) != 1) failed = 1;
    if (!failed && printf("%.1f\n", value) < 0) failed = 1;
    if (fclose(file) != 0) failed = 1;
    return failed ? EXIT_FAILURE : EXIT_SUCCESS;
}

nodes.body:
# 第14章 结构和其他数据形式

结构把一条记录的相关数据放在同一个对象里；结构数组保存多条记录，结构指针和函数接口则决定怎样访问与传递。后面还会认识共享存储的联合、命名整数值的枚举、类型别名与函数指针。

### 完整初始化、部分初始化与随后更新记录（完整C程序）

```c
#include <stdio.h>

struct Book {
    char title[24];
    char author[16];
    float price;
    int copies;
};

int main(void)
{
    struct Book book = { // 初始化时，初值按成员的声明顺序对应。
        "C Steps",
        "Lin",
        12.50f,
        2
    };
    struct Book draft = {"Draft"}; // 部分初始化：其余成员也初始化；作者为空串，价格和数量为零。
    float total = book.price * book.copies;

    printf("initial: %s | %s | price=%.2f | copies=%d | total=%.2f\n",
           book.title, book.author, book.price, book.copies, total);
    printf("partial: %s | author=<%s> | price=%.2f | copies=%d\n",
           draft.title, draft.author, draft.price, draft.copies);

    book.price = 10.00f;
    book.copies = book.copies + 1;
    total = book.price * book.copies;
    printf("updated: %s | %s | price=%.2f | copies=%d | total=%.2f\n",
           book.title, book.author, book.price, book.copies, total);
    return 0;
}
```

**输入**：无需输入。

**真实C6运行结果**：

```text
initial: C Steps | Lin | price=12.50 | copies=2 | total=25.00
partial: Draft | author=<> | price=0.00 | copies=0
updated: C Steps | Lin | price=10.00 | copies=3 | total=30.00
```

book把书名、作者、单价和数量关联在一起，draft是另一条独立记录。初始化与后续更新都围绕各自成员进行，不需要用几组平行数组的相同下标来猜测信息属于哪本书。

本章重点是数据表示与访问关系：对象实际包含哪些数据，哪些成员只是指向别处，复制后是否仍共享目标，函数收到的是值还是地址。完整程序会随主题保留；结构按值传递、联合、动态尾数组与函数指针等支持外内容按标准C阅读。

# 14.1 示例问题：创建图书目录

图书目录的一条记录需要同时保存文本和数值。数组要求元素类型一致，结构则让每个成员有自己的类型，并共同属于一条记录；再建立结构数组，就能把多本书组织成同一种元素。

### 每个数组元素是一条完整结构记录（完整C程序）

```c
#include <stdio.h>
struct Book { char title[8]; int copies; float price; };
int main(void)
{
    struct Book books[2] = {{"Elm", 2, 4.5f}, {"Oak", 1, 3.0f}};
    float total = 0.0f;
    for (int i = 0; i < 2; ++i) {
        printf("%s copies=%d\n", books[i].title, books[i].copies);
        total += books[i].copies * books[i].price;
    }
    printf("total=%.2f last=%c\n", total, books[1].title[2]);
    return 0;
}
```

**输入**：无需输入。

**真实C6运行结果**：

```text
Elm copies=2
Oak copies=1
total=12.00 last=k
```

books[0]保存Elm这本书的名称、数量和价格，books[1]保存Oak的对应信息。计算每条记录的金额时，名称与数值不会因为另一组数组漏改下标而脱节。这里总额为12，第二条书名的第三个字符为k。

结构首先改善的是数据关系表达，不自动提供排序、输入验证或文件保存。成员类型仍需满足业务需求；本章用能准确表示的简单价格看清数据变化，不把浮点数视为所有金额业务都无需舍入处理的通用表示。

# 14.2 建立结构声明

结构定义列出成员的名称和类型，建立一种记录的组织方式。单独的`struct Stock { ... };`定义类型，并不创建一条名叫Stock的实际库存记录；随后还要用这个类型定义对象。

### 只把计算需要的两个成员值传给函数（完整C程序）

```c
#include <stdio.h>
struct Stock { float price; int copies; };
float cost(float price, int copies)
{
    return price * copies;
}
int main(void)
{
    struct Stock stock = {12.5f, 2};
    printf("%.2f copies=%d\n", cost(stock.price, stock.copies), stock.copies);
    return 0;
}
```

**输入**：无需输入。

**真实C6运行结果**：

```text
25.00 copies=2
```

struct Stock有price与copies两个成员，stock才是一条实际对象。cost只接收两个成员值，不需要知道它们来自结构。结构体末尾的分号结束类型声明，成员各自的分号结束内部声明，不能用初始化列表的逗号替代。

结构标记与普通变量名不是一回事，在C中引用带标记类型通常写完整的struct Stock，除非另有typedef别名。成员也并非可以随意选任何类型：可以包含适当的完整对象类型或指针，不能直接内含一个尚未完成的自身实例，也不能把普通函数或VLA直接当作结构成员。值嵌套与指向另一对象会在后面分别讨论。

# 14.3 定义结构变量

同一种结构类型可以建立多条对象，每条都有自己的成员存储。定义结构对象与声明一个结构指针也不同：前者提供记录本身，后者只提供保存访问地址的指针对象。

### 点运算符取得成员，成员保留自己的类型（完整C程序）

```c
#include <stdio.h>
struct Book { char title[8]; int copies; float price; };
int main(void)
{
    struct Book book = {"elm", 2, 4.50f};
    book.title[0] = 'E';
    if (scanf("%d", &book.copies) != 1) {
        puts("no count");
        return 0;
    }
    printf("%s copies=%d price=%.2f\n", book.title, book.copies, book.price);
    return 0;
}
```

**输入**：

```text
3
```

**真实C6运行结果**：

```text
Elm copies=3 price=4.50
```

book拥有八项title数组、一项copies和一项price。取得copies的地址后，scanf把成功转换的数值写入这条记录的该成员；失败时程序不继续按新输入显示记录。title的修改也只发生在book自己的数组里。

标准C还允许把类型定义与对象声明合写，或定义没有标记的结构类型；但两次独立类型定义不因成员外形相同就自动成为同一类型。定义时没有初始化器的普通自动结构对象，也不能一概按全零成员使用；下一节会区分完整初始化、部分初始化与没有初始化。

# 14.3.2 访问结构成员

点运算符从结构对象中选择成员，所选表达式保留成员自己的类型。book.copies是int，book.price是float，book.title是字符数组；结构没有把它们都变成一种通用值。

### 点运算符取得成员，成员保留自己的类型（完整C程序）

```c
#include <stdio.h>
struct Book { char title[8]; int copies; float price; };
int main(void)
{
    struct Book book = {"elm", 2, 4.50f};
    book.title[0] = 'E';
    if (scanf("%d", &book.copies) != 1) {
        puts("no count");
        return 0;
    }
    printf("%s copies=%d price=%.2f\n", book.title, book.copies, book.price);
    return 0;
}
```

**输入**：

```text
3
```

**真实C6运行结果**：

```text
Elm copies=3 price=4.50
```

`&book.copies`取得该int成员的地址，可交给%d转换的目标参数。点号结合比取地址更紧，因此这里对应`&(book.copies)`。访问title中的字符则继续加下标，`book.title[0]`才是其中一个char元素。

结构对象之间的同名成员分别属于各自记录，不能省略对象只写copies来选择某条记录。数组成员仍遵守数组规则：定义时可由字符串初始化，之后不能写`book.title = "Other";`进行数组整体赋值。修改文本需要在有效容量与终止符约束下写入字符或复制内容。

# 14.3.3 结构的初始化器

指定初始化器用点号和成员名说明初值去向，不必按声明次序逐项列出。它仍是对象定义时的初始化规则，不是执行到一半再向结构中添加字段。

### 指定成员后，普通初值继续对应后续成员（完整标准C阅读程序）

结构指定初始化器不在C6范围。下面是完整C99及以后标准C阅读程序。

```c
#include <stdio.h>
struct Book { char title[8]; float price; int copies; };
int main(void)
{
    struct Book first = {.copies = 3};
    struct Book second = {.price = 8.0f, .title = "Elm", 4.5f};
    printf("first=<%s> %.1f %d\n", first.title, first.price, first.copies);
    printf("second=%s %.1f %d\n", second.title, second.price, second.copies);
    return 0;
}
```

**教学预期（非本平台实测）**：first只指定copies，title为空、price为0、copies为3；second先指定price为8，再指定title为Elm，后面的4.5对应price，故最终price为4.5、copies为0。重复指定不要求被覆盖的初始化表达式必定求值。

first只给copies提供3，其余成员按省略初始化项的规则取得零值，所以title为空字符串、price为0。second先给price提供8，再转向title；其后的普通4.5继续对应title后面的price，因此最终价格为4.5，copies为0。

重复指定决定哪个初值最终生效，但不能用被覆盖表达式的副作用安排执行顺序；被覆盖的初始化表达式不一定会求值。指定成员还必须确实存在且初值类型合适，拼错名字不会自动生成新成员。

# 14.4 结构数组

结构数组让每个元素保存一条完整记录。数组本身仍有统一元素类型与固定容量，结构成员则在每条记录内部保留各自类型；外层数组与内层字段不能混为一个层次。

### 每个数组元素是一条完整结构记录（完整C程序）

```c
#include <stdio.h>
struct Book { char title[8]; int copies; float price; };
int main(void)
{
    struct Book books[2] = {{"Elm", 2, 4.5f}, {"Oak", 1, 3.0f}};
    float total = 0.0f;
    for (int i = 0; i < 2; ++i) {
        printf("%s copies=%d\n", books[i].title, books[i].copies);
        total += books[i].copies * books[i].price;
    }
    printf("total=%.2f last=%c\n", total, books[1].title[2]);
    return 0;
}
```

**输入**：无需输入。

**真实C6运行结果**：

```text
Elm copies=2
Oak copies=1
total=12.00 last=k
```

循环中的i先选择哪一本书，再用title、copies与price选择这本书的字段。总额依次增加9和3。两条title数组各有自己的八项容量，第二条的字符下标2不会访问第一条书名。

较大结构数组会占用更多存储，但不能把所有自动数组都描述成必然放在某种固定宿主栈中，也不能照搬旧编译器的栈大小数值作为通用解法。应根据实际容量、对象寿命与执行环境选择存储策略，不能只因为出现内存问题就盲目加static。

# 14.4.1 声明结构数组

`struct Book books[2]`建立两个struct Book元素，不是两个数组，也不是一个含两本书信息的结构成员。初始化的外层列表对应各个数组元素，各元素自己的列表再对应其结构成员。

### 每个数组元素是一条完整结构记录（完整C程序）

```c
#include <stdio.h>
struct Book { char title[8]; int copies; float price; };
int main(void)
{
    struct Book books[2] = {{"Elm", 2, 4.5f}, {"Oak", 1, 3.0f}};
    float total = 0.0f;
    for (int i = 0; i < 2; ++i) {
        printf("%s copies=%d\n", books[i].title, books[i].copies);
        total += books[i].copies * books[i].price;
    }
    printf("total=%.2f last=%c\n", total, books[1].title[2]);
    return 0;
}
```

**输入**：无需输入。

**真实C6运行结果**：

```text
Elm copies=2
Oak copies=1
total=12.00 last=k
```

第一组初值属于books[0]，第二组属于books[1]；每组的顺序仍跟随title、copies、price的声明次序。数组长度为2，可用元素下标只有0和1，不能因为每个结构有三个成员就把books[2]当成第三个字段。

数组元素连续排列，步长是sizeof(struct Book)，其中可能包含实现为对齐加入的填充。因此总占用由元素大小与数量共同决定，不能只把可见字符串长度相加，也不能假定所有结构都没有内部或尾部空隙。

# 14.4.2 标识结构数组的成员

访问结构数组要先取得某一元素，再选择它的成员；如果成员自身也是数组，才继续使用第二层下标。每一个运算符都对应当前表达式的真实类型。

### 每个数组元素是一条完整结构记录（完整C程序）

```c
#include <stdio.h>
struct Book { char title[8]; int copies; float price; };
int main(void)
{
    struct Book books[2] = {{"Elm", 2, 4.5f}, {"Oak", 1, 3.0f}};
    float total = 0.0f;
    for (int i = 0; i < 2; ++i) {
        printf("%s copies=%d\n", books[i].title, books[i].copies);
        total += books[i].copies * books[i].price;
    }
    printf("total=%.2f last=%c\n", total, books[1].title[2]);
    return 0;
}
```

**输入**：无需输入。

**真实C6运行结果**：

```text
Elm copies=2
Oak copies=1
total=12.00 last=k
```

`books[1].title[2]`依次选择第二条Book记录、其中的title数组、数组的第三个字符，得到k。`books[1].copies`则直接得到第二条记录的整数数量，不需要再对该标量加下标。

`books.price[1]`不成立，因为books是数组而不是带price成员的结构。检查访问表达式时从左到右辨认当前层次，比把所有点号和方括号都当作可互换的“下标”更可靠；两个索引的范围也必须分别满足外层记录数和内层成员容量。

# 14.4.3 程序讨论

输入多条记录时，数组容量与已经完成的记录数是两回事。只有一条记录需要的字段都取得后，才能增加有效数量；否则后续输出可能读到尚未建立的成员值。

### 所有字段取得后，才把记录计入有效数量（完整C程序）

```c
#include <stdio.h>
#include <string.h>
struct Book { char title[8]; int copies; };
int read_title(char *text)
{
    if (fgets(text, 8, stdin) == 0) return 0;
    char *newline = strchr(text, '\n');
    if (newline != 0) {
        *newline = '\0';
        return 1;
    }
    int ch = getchar();
    if (ch == '\n' || ch == EOF) return 1;
    while ((ch = getchar()) != '\n' && ch != EOF) {}
    return -1;
}
int main(void)
{
    struct Book books[2];
    int count = 0;
    while (count < 2) {
        int status = read_title(books[count].title);
        if (status == 0) break;
        if (status < 0) {
            puts("too long");
            continue;
        }
        if (books[count].title[0] == '\0') break;
        if (scanf("%d", &books[count].copies) != 1) break;
        int ch;
        while ((ch = getchar()) != '\n' && ch != EOF) {}
        ++count; // 只有书名和数量都取得后，这条记录才算有效。
        if (ch == EOF) break;
    }
    printf("count=%d\n", count);
    for (int i = 0; i < count; ++i)
        printf("%s:%d\n", books[i].title, books[i].copies);
    return 0;
}
```

**输入**：

```text
Elm
2
Oak
1
```

**真实C6运行结果**：

```text
count=2
Elm:2
Oak:1
```

count在成功取得书名与数量之后才增加。读取书名失败、空书名或数量转换失败都会在提交记录前停止；过长书名整行丢弃后重试。默认输入得到两条完整记录，若输入在Elm书名后结束，则有效数量仍为0；数量2后直接EOF则已有一条完整记录，可以输出它。

scanf留下的行尾由读取循环清理，同时检查LF与EOF，避免末行没有LF时无限等待。这里约定数量文本可由int表示，按一次转换取得数值，丢弃本行余项；它不是验证任意长度整数或整行无其他内容的通用解析器。输出只遍历count项，既不超过容量，也不展示未完成记录。

# 14.5 嵌套结构

嵌套结构把某组紧密相关的字段再组织成一个子对象。例如姓名由名与姓组成，个人记录还包括编号；把姓名单独定义成类型，可以在其他记录中复用相同组织方式。

### 一个成员本身也是结构对象（完整标准C阅读程序）

值形式的嵌套结构不在C6范围。下面是完整标准C阅读程序，保留真实的嵌套类型。

```c
#include <stdio.h>
struct Name { char first[8]; char last[8]; };
struct Person { int id; struct Name name; };
int main(void)
{
    struct Person person = {7, {"Ana", "Li"}};
    printf("%d %s %s\n", person.id, person.name.first, person.name.last);
    return 0;
}
```

**教学预期（非本平台实测）**：输出7 Ana Li。person.name取得内层结构，再通过first、last访问其中数组；两个字符串都是外层对象所含子对象的一部分。

person.name本身是一个struct Name对象，再选择first或last才得到字符数组。内层花括号与这一层组织对应，初始化7后再为姓名的两个字段提供Ana与Li。字符串存储属于这条Person记录内含的子对象。

值嵌套确实内含子对象，和只保存另一条记录的指针不同：前者的空间与寿命随外层对象，后者还要判断目标对象是否存在以及由谁拥有。值嵌套与指针成员不能互换，所需存储与寿命关系会随之改变。

# 14.6 指向结构的指针

结构指针保存访问某种结构对象的地址，便于选择记录、通过函数访问原对象或连接其他节点。声明指针不会自动建立它所指的结构，也不会自动让它指向一条有效记录。

### 结构指针与两种成员访问写法（完整C程序）

```c
#include <stdio.h>
struct Stock { int copies; };
int main(void)
{
    struct Stock stock = {2};
    struct Stock *selected = &stock;
    selected->copies = 4;
    printf("dot=%d arrow=%d dereferenced=%d same=%d\n",
           stock.copies, selected->copies, (*selected).copies, selected == &stock);
    return 0;
}
```

**输入**：无需输入。

**真实C6运行结果**：

```text
dot=4 arrow=4 dereferenced=4 same=1
```

selected由&stock取得有效地址，经箭头写入copies后，点号、箭头和括号解引用三种访问都读到4。它们访问同一成员，并没有为每种写法建立一条副本。

选用指针后还要持续检查类型、空值、目标寿命和可写性。平台使用教学虚拟地址呈现对象，不能由地址数值推断宿主物理布局。对数组元素的前进可以按结构步长进行，但不能拿两个无关对象假定相邻来遍历。

# 14.6.1 声明和初始化结构指针

结构指针的类型写作struct加标记再加星号，初始化时提供相容对象地址。普通结构对象不会像数组表达式那样自动转换成首元素指针，需要显式使用取地址运算符。

### 结构指针前进一项，访问下一个完整记录（完整C程序）

```c
#include <stdio.h>
struct Stock { char code[4]; int copies; };
int main(void)
{
    struct Stock stocks[2] = {{"elm", 2}, {"oak", 3}};
    struct Stock *selected = stocks;
    printf("%s:%d\n", selected->code, selected->copies);
    ++selected;
    printf("%s:%d\n", selected->code, selected->copies);
    return 0;
}
```

**输入**：无需输入。

**真实C6运行结果**：

```text
elm:2
oak:3
```

stocks在这个表达式中转换为首元素指针，selected先访问elm记录，前进一项后访问oak记录。若是单独一条stock对象，则应写&stock，不能直接把stock的结构值赋给结构指针。

前进一项按sizeof所指结构移动，包含实现的对齐与填充，不能固定成书中某次观察到的84字节。指针运算的有效范围仍限制在同一数组及允许形成的尾后一位，尾后一位不能解引用；指针存在也不延长数组元素的寿命。

# 14.6.2 用指针访问成员

箭头运算符用来从结构指针选择目标成员。对有效的结构指针selected，`selected->copies`与`(*selected).copies`表达相同的成员访问，左操作数的类型决定该用箭头还是点号。

### 结构指针与两种成员访问写法（完整C程序）

```c
#include <stdio.h>
struct Stock { int copies; };
int main(void)
{
    struct Stock stock = {2};
    struct Stock *selected = &stock;
    selected->copies = 4;
    printf("dot=%d arrow=%d dereferenced=%d same=%d\n",
           stock.copies, selected->copies, (*selected).copies, selected == &stock);
    return 0;
}
```

**输入**：无需输入。

**真实C6运行结果**：

```text
dot=4 arrow=4 dereferenced=4 same=1
```

selected是指针，stock是结构对象，因此使用`selected->copies`和`stock.copies`。括号必须保留：点号结合更紧，去掉括号的`*selected.copies`会先试图从指针selected选择copies，并不是先解引用后选择成员。

成员表达式的类型仍是int，而不是结构指针类型；需要成员地址时，可以在合法成员访问上再取地址。若指针为空、已悬挂或目标只允许读取，箭头不会替你解决这些问题，访问仍需满足原对象的边界与权限。

# 14.7 向函数传递结构的信息

向函数提供结构信息，可以只传需要的成员值、传结构地址，或者按标准C规则传整个结构值。选择取决于函数需要哪些数据、是否要修改原记录，以及接口怎样表达结果。

### 通过结构指针修改原记录，再只读计算（完整C程序）

```c
#include <stdio.h>
struct Stock { int copies; float price; };
void add_copy(struct Stock *stock)
{
    ++stock->copies;
}
float cost(const struct Stock *stock)
{
    return stock->copies * stock->price;
}
int main(void)
{
    struct Stock stock = {2, 5.0f};
    add_copy(&stock);
    printf("copies=%d cost=%.2f\n", stock.copies, cost(&stock));
    return 0;
}
```

**输入**：无需输入。

**真实C6运行结果**：

```text
copies=3 cost=15.00
```

add_copy收到结构指针，能修改原stock的数量；cost也收到指针，但类型提供只读结构访问。调用者在修改后读到copies为3、金额为15。指针参数本身仍是按值传递，能改原对象是因为这份指针值指向它。

### 结构参数是副本，返回结构值再保存结果（完整标准C阅读程序）

结构按值参数、返回和整体复制不在C6范围。下面是完整标准C阅读程序。

```c
#include <stdio.h>
struct Point { int x; int y; };
struct Point moved(struct Point value)
{
    value.x += 2;
    return value;
}
int main(void)
{
    struct Point original = {1, 3};
    struct Point copy = moved(original);
    copy.y = 8;
    printf("original=%d,%d copy=%d,%d\n",
           original.x, original.y, copy.x, copy.y);
    return 0;
}
```

**教学预期（非本平台实测）**：original保持1、3；moved返回3、3，copy自己的y再改为8，最终输出original=1,3 copy=3,8。返回的是结构值，不是已经结束寿命的局部对象地址。

第二份完整程序改用结构值与返回值，moved处理自己的参数副本，original保持1、3。不能把“所有参数都是一个数字或地址”的旧简化说法推广到结构参数，也不能把一次传指针与一次传结构的输出相似，当成它们具有同样的对象关系。

# 14.7.1 传递结构成员

若函数只需要几个成员值，可以直接把这些表达式作为实参。函数看到的是各自声明的参数类型，不需要了解实参是否来自结构、数组元素还是普通变量。

### 只把计算需要的两个成员值传给函数（完整C程序）

```c
#include <stdio.h>
struct Stock { float price; int copies; };
float cost(float price, int copies)
{
    return price * copies;
}
int main(void)
{
    struct Stock stock = {12.5f, 2};
    printf("%.2f copies=%d\n", cost(stock.price, stock.copies), stock.copies);
    return 0;
}
```

**输入**：无需输入。

**真实C6运行结果**：

```text
25.00 copies=2
```

cost收到float价格与int数量，求得25；接口没有接收整个Stock类型。这样函数只依赖所需信息，若结构增加无关成员，求金额的函数也不必跟着改变。

需要修改原成员时，单传成员值不够，可以另行传该成员的地址，或传结构地址。数组成员作为实参时通常会转换为指向首元素的指针，不能把“传成员”都理解成复制一份独立数据；仍要按该成员的类型和表达式规则判断。

# 14.7.2 传递结构的地址

传结构地址能让函数访问原记录的多个成员，也能在接口允许时修改它们。指针形参应明确所指结构类型，并在只需读取时使用适当const限定来表达访问意图。

### 通过结构指针修改原记录，再只读计算（完整C程序）

```c
#include <stdio.h>
struct Stock { int copies; float price; };
void add_copy(struct Stock *stock)
{
    ++stock->copies;
}
float cost(const struct Stock *stock)
{
    return stock->copies * stock->price;
}
int main(void)
{
    struct Stock stock = {2, 5.0f};
    add_copy(&stock);
    printf("copies=%d cost=%.2f\n", stock.copies, cost(&stock));
    return 0;
}
```

**输入**：无需输入。

**真实C6运行结果**：

```text
copies=3 cost=15.00
```

add_copy的结构指针允许修改copies，cost的const结构指针只读取copies与price。调用时都提供&stock，函数体再用箭头选择成员；并没有把stock自动转换成地址。

const限制通过该结构访问路径修改直接成员，并不把所有别名或所有指针所指对象都递归冻结。若结构含一个指向可写字符的指针，即使结构经只读路径访问，目标字符仍需另行限定。接口还应约定非空、有效寿命及允许修改范围，不能把指针参数本身当作有效性证明。

# 14.7.3 传递结构

按值传结构时，函数的形参是自己的结构对象，取得实参成员值的副本。修改形参的普通数值成员不会直接改写调用者的对应成员；需要把结果交回时，可以返回一个结构值。

### 结构参数是副本，返回结构值再保存结果（完整标准C阅读程序）

结构按值参数、返回和整体复制不在C6范围。下面是完整标准C阅读程序。

```c
#include <stdio.h>
struct Point { int x; int y; };
struct Point moved(struct Point value)
{
    value.x += 2;
    return value;
}
int main(void)
{
    struct Point original = {1, 3};
    struct Point copy = moved(original);
    copy.y = 8;
    printf("original=%d,%d copy=%d,%d\n",
           original.x, original.y, copy.x, copy.y);
    return 0;
}
```

**教学预期（非本平台实测）**：original保持1、3；moved返回3、3，copy自己的y再改为8，最终输出original=1,3 copy=3,8。返回的是结构值，不是已经结束寿命的局部对象地址。

moved把自己的value.x由1改为3并返回，copy接收这个结果，再把自己的y改成8。original仍为1、3，说明这里不是把原对象地址换个名字继续使用。返回结构值也不是返回局部value的地址，因此没有产生同一种悬挂地址问题。

结构副本内若含指针，复制的仍是指针值，目标不会自动深复制；所以“按值”也不能保证通过任何成员都不影响外部数据。按值传递需要函数签名与实参结构类型相容，并保证被复制和使用的成员已取得有效值。

# 14.7.4 其他结构特性

标准C允许相容结构类型的对象整体赋值，也允许从同类型结构值初始化新对象或返回结构。成员值随之复制，包括结构内含的数组成员；这与直接对一个独立数组使用整体赋值不同。

### 结构复制包含数组值，指针成员仍共享目标（完整标准C阅读程序）

结构整体复制不在C6范围。下面是完整标准C阅读程序，分别展示自有数组与借用指针的复制效果。

```c
#include <stdio.h>
struct Text { char owned[8]; char *borrowed; };
int main(void)
{
    char shared[8] = "oak";
    struct Text original = {"elm", shared};
    struct Text copy = original;
    copy.owned[0] = 'E';
    copy.borrowed[0] = 'O';
    printf("original=%s copy=%s shared=%s same=%d\n",
           original.owned, copy.owned, shared, original.borrowed == copy.borrowed);
    return 0;
}
```

**教学预期（非本平台实测）**：original.owned仍是elm，copy.owned变成Elm；两份borrowed都访问同一个shared数组，后者变成Oak，same为1。没有为borrowed自动建立第二份字符存储。

copy.owned得到独立的数组成员内容，改首字符后只让它变成Elm，original.owned仍是elm。borrowed复制的却只是地址，两条记录仍指向shared，所以经copy.borrowed修改后，共同目标变成Oak。

这说明复制值与复制目标存储有区别，不能把有指针的结构整体赋值叫作自动深复制。结构还不能直接用==或!=比较整个对象；需要按业务含义比较成员。用原始字节比较也可能受填充字节影响，不能自动等价于成员值相等。

# 14.7.5 结构和结构指针的选择

按值接口适合表达独立的小型值及返回结果，指针接口适合访问现有记录、可选地修改原对象，或避免接口层面的大量值复制。选择时要同时看语义与实际需求，不能只背“指针永远更快”。

### 结构参数是副本，返回结构值再保存结果（完整标准C阅读程序）

结构按值参数、返回和整体复制不在C6范围。下面是完整标准C阅读程序。

```c
#include <stdio.h>
struct Point { int x; int y; };
struct Point moved(struct Point value)
{
    value.x += 2;
    return value;
}
int main(void)
{
    struct Point original = {1, 3};
    struct Point copy = moved(original);
    copy.y = 8;
    printf("original=%d,%d copy=%d,%d\n",
           original.x, original.y, copy.x, copy.y);
    return 0;
}
```

**教学预期（非本平台实测）**：original保持1、3；moved返回3、3，copy自己的y再改为8，最终输出original=1,3 copy=3,8。返回的是结构值，不是已经结束寿命的局部对象地址。

Point可以自然表达一个坐标值，moved接收值并返回新值，使原坐标保留。调用者显式保存返回结果，接口本身就能说明它产生另一份坐标，而不是在函数里悄悄修改原记录。

若函数只需要一个字段，单传该字段可能更清楚；若需要修改原记录，结构指针能明确这份关系。指针也有别名与有效性责任，const只读接口不能代替深层所有权设计。实际机器上的复制开销还受结构大小、调用约定与优化影响，不应从一份教学输出声称测得某种性能优势。

# 14.7.6 结构中的字符数组和字符指针

字符数组成员提供结构自己内含的字符空间，字符指针成员只提供地址存储。二者都能用于读取字符串，但容量来源、可写性、寿命和复制关系不同。

### 结构拥有字符数组，指针只保存访问路径（完整C程序）

```c
#include <stdio.h>
struct Text { char owned[8]; const char *borrowed; };
int main(void)
{
    struct Text text = {"elm", "oak"};
    printf("before=%s/%s\n", text.owned, text.borrowed);
    text.owned[0] = 'E';
    text.borrowed = text.owned;
    printf("after=%s/%s\n", text.owned, text.borrowed);
    return 0;
}
```

**输入**：无需输入。

**真实C6运行结果**：

```text
before=elm/oak
after=Elm/Elm
```

最初owned保存elm的字符副本，borrowed指向只读访问的oak字面量。修改owned首字符并让borrowed指向owned后，两个访问都显示Elm；改变指针值没有再复制一份字符串，也没有让字面量本身发生变化。

不能只声明一个未初始化字符指针成员，就把它交给字符串输入函数；那还没有提供有效目标存储。数组成员也需要正确容量与终止符，指针成员则还要知道目标是否仍然存在。结构整体复制会复制内含数组值，却只复制指针地址；是否需要独立文本副本，应由所有权约定决定。

# 14.7.7 结构、指针和malloc()

结构可以用指针成员记录动态分配的字符串地址，以便按需要选择容量。取得分配后，字符仍位于结构外部；结构只是持有访问与管理这些区域的指针。

### 结构中的两个指针分别拥有动态字符串（完整标准C阅读程序）

malloc、free与动态存储不在C6范围。下面是完整标准C阅读程序，字符串数据由程序提供。

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
struct Name { char *first; char *last; };
int main(void)
{
    struct Name person = {NULL, NULL};
    person.first = malloc(sizeof "Ana");
    if (person.first == NULL) return EXIT_FAILURE;
    person.last = malloc(sizeof "Li");
    if (person.last == NULL) {
        free(person.first);
        return EXIT_FAILURE;
    }
    strcpy(person.first, "Ana");
    strcpy(person.last, "Li");
    int failed = printf("%s %s\n", person.first, person.last) < 0;
    free(person.first);
    free(person.last);
    return failed ? EXIT_FAILURE : EXIT_SUCCESS;
}
```

**教学预期（非本平台实测）**：两次分配都成功时，输出Ana Li，再分别释放两份分配。第二次分配失败时先释放已经取得的first，再失败返回；结构本身没有内含这两份字符串字符。

两次malloc分别为Ana及Li连同NUL提供空间，成功后才复制字符。第二次失败会先释放第一次已经取得的分配，避免只处理正常结尾而遗漏中途失败路径。打印后再分别free，完成本程序拥有的两份资源。

这里用sizeof字符串字面量自然包含结束符；按输入长度分配时也需要为NUL留位置。复制一份这样的结构会复制所有权相关地址，不能让两个副本都无约定地free同一分配。应明确谁拥有、谁借用、何时转交；即使结构本身也由malloc分配，free结构所在分配也不会自动释放其指针成员所指区域。

# 14.7.8 复合字面量和结构（C99）

复合字面量把类型名与初始化列表组合成一个没有普通变量名的对象，既可以使用它的结构值，也可以在有效寿命内取其地址。它不是把裸花括号变成任意位置都可使用的普通表达式。

### 复合字面量提供一个结构对象及其值（完整标准C阅读程序）

结构复合字面量与按值结构参数不在C6范围。下面是完整C99及以后标准C阅读程序。

```c
#include <stdio.h>
struct Point { int x; int y; };
int sum(struct Point point)
{
    return point.x + point.y;
}
int sum_at(const struct Point *point)
{
    return point->x + point->y;
}
int main(void)
{
    struct Point point = {0, 0};
    point = (struct Point){.y = 4, .x = 2};
    printf("%d\n", sum(point));
    printf("%d\n", sum_at(&(struct Point){3, 5}));
    return 0;
}
```

**教学预期（非本平台实测）**：point成为2、4，sum输出6；第二次把块内复合字面量3、5的地址传入只读函数，输出8。调用期间对象有效，不返回这份块内对象的地址供块外继续使用。

`(struct Point){.y = 4, .x = 2}`提供一个Point对象的值，整体赋给point后，两坐标为2与4。第二次调用则取得另一份复合字面量的地址，让sum_at读取3与5，得到8；值接口与地址接口仍有不同类型。

块内复合字面量具有相应块的自动存储期，不会在函数返回后因为某处还保存地址就继续存在；文件作用域的复合字面量则具有静态存储期。不要把C的这个对象一概说成只活到当前完整表达式结束的临时值。

# 14.7.9 伸缩型数组成员（C99）

伸缩型数组成员把一个不指定长度的数组放在结构最后，用同一次额外分配容纳实际元素。在它之前至少还要有一个有名成员；数组长度不由结构声明内的空方括号自动取得。

### 为结构头和伸缩数组一起分配足够空间（完整标准C阅读程序）

伸缩型数组成员与动态分配不在C6范围。下面是完整C99及以后标准C阅读程序。

```c
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
struct Scores { size_t count; double average; double values[]; };
int main(void)
{
    size_t count = 3;
    if (count > (SIZE_MAX - sizeof(struct Scores)) / sizeof(double))
        return EXIT_FAILURE;
    struct Scores *scores = malloc(sizeof *scores + count * sizeof scores->values[0]);
    if (scores == NULL) return EXIT_FAILURE;
    scores->count = count;
    double total = 0.0;
    for (size_t i = 0; i < count; ++i) {
        scores->values[i] = 2.5 + i;
        total += scores->values[i];
    }
    scores->average = total / count;
    int failed = printf("count=%zu average=%.1f\n", scores->count, scores->average) < 0;
    free(scores);
    return failed ? EXIT_FAILURE : EXIT_SUCCESS;
}
```

**教学预期（非本平台实测）**：大小检查通过且分配成功时，count为3，values保存2.5、3.5、4.5，average为3.5，随后释放。sizeof结构头不随count改变，尾部容量由这次分配决定。

本次为结构头和三个double分配足够空间，count记录业务上的元素数，values依次写入2.5、3.5、4.5。累计用double保留小数，平均为3.5。先检查乘积与加法可表示，再malloc并检查空指针，最后整体free。

sizeof结构类型不随count改变，也不把运行时尾部元素全部算入其中。普通结构赋值不能用来完整复制这份尾数组，修改count也不会自动扩容；复制需要同时知道真实容量与完整字节范围。带伸缩数组的结构不能作为另一结构的普通成员或数组元素，不能用非标准零长度数组技巧替代这一标准约定。

# 14.7.10 匿名结构（C11）

C11匿名结构成员省略的是内层成员名称，使内层成员能像外层成员一样被选择。它与“没有标记但有变量名的结构类型”不是同一概念，也没有移除内部子对象的组织层次。

### 匿名结构成员省去中间的成员名（完整标准C阅读程序）

C11匿名结构成员不在C6范围。下面是完整标准C阅读程序，匿名的是成员，不只是类型没有标记。

```c
#include <stdio.h>
struct Person {
    int id;
    struct { char first[8]; char last[8]; };
};
int main(void)
{
    struct Person person = {7, {"Ana", "Li"}};
    printf("%d %s %s\n", person.id, person.first, person.last);
    return 0;
}
```

**教学预期（非本平台实测）**：输出7 Ana Li。内层结构没有成员名，first与last可直接通过person访问；初始化仍按嵌套层次组织。

person里仍有一组嵌套的姓名字段，初始化用内层花括号对应Ana和Li；访问时却可以直接写person.first与person.last，不再经过name这一层成员名。

这是访问语法便利，不是自动合并所有同名字段。匿名成员暴露到外层后也要避免名字冲突，并继续遵守结构布局、初始化和存储规则。

# 14.7.11 使用结构数组的函数

数组作为函数实参通常转换为首元素指针，结构数组也遵守这个规则。被调函数拿到访问首条结构的路径，并不会自动得到实参数组长度，所以还要传有效数量或采用其他明确边界协议。

### 结构数组形参仍需独立传有效元素数量（完整C程序）

```c
#include <stdio.h>
struct Stock { int copies; float price; };
float cost_all(const struct Stock *stocks, int count)
{
    float total = 0.0f;
    for (int i = 0; i < count; ++i)
        total += stocks[i].copies * stocks[i].price;
    return total;
}
int main(void)
{
    struct Stock stocks[2] = {{2, 4.5f}, {1, 3.0f}};
    int count;
    if (scanf("%d", &count) != 1 || count < 0 || count > 2) {
        puts("invalid count");
        return 0;
    }
    printf("%.2f\n", cost_all(stocks, count));
    return 0;
}
```

**输入**：

```text
2
```

**真实C6运行结果**：

```text
12.00
```

stocks有两项，调用者先把count限制为0至2，再交给cost_all。count为2时合计12，为0时不访问任何元素而返回0；3与负值都在调用前拒绝。函数中的stocks[i]仍是结构元素，再用点号取得copies和price。

这里const限制通过该接口修改结构成员，count规定可访问的项数，两者职责不同。写成数组形参形式也不会让sizeof形参恢复原数组容量。若数组中有未完成记录，实际有效数量还应小于或等于容量，不能把全部声明长度都传过去当作已初始化数据。

# 14.8 把结构内容保存到文件中

一条结构可以对应一条记录，但文件格式仍需另外设计。按字段输出文本便于明确编码与分隔；按sizeof原样写出则保存当前实现的对象表示，可能同时包含填充和未使用数组空间。

### 同一实现内原样保存并恢复一条无指针记录（完整标准C阅读程序）

FILE、fread、fwrite不在C6范围。下面是完整标准C阅读程序，临时文件只读取本程序自己写入的兼容对象表示。

```c
#include <stdio.h>
#include <stdlib.h>
struct Book { char title[8]; int copies; float price; };
int main(void)
{
    struct Book book = {"Elm", 2, 4.5f};
    struct Book restored;
    FILE *file = tmpfile();
    if (file == NULL) return EXIT_FAILURE;
    int failed = fwrite(&book, sizeof book, 1, file) != 1;
    if (!failed && fseek(file, 0L, SEEK_SET) != 0) failed = 1;
    if (!failed && fread(&restored, sizeof restored, 1, file) != 1) failed = 1;
    if (!failed && printf("%s %d %.2f\n",
                          restored.title, restored.copies, restored.price) < 0) failed = 1;
    if (fclose(file) != 0) failed = 1;
    return failed ? EXIT_FAILURE : EXIT_SUCCESS;
}
```

**教学预期（非本平台实测）**：流与传输、定位、关闭都成功时，恢复Elm、2、4.5，输出Elm 2 4.50。结构可能有填充；文件大小按sizeof而非成员大小之和，也不保证跨实现可读。

这份程序只从自己的临时文件恢复自己刚写入的同布局记录，完整读到一项后才把title当字符串使用。sizeof book决定整项大小，不使用某台机器上的成员大小相加结果替代它。

原生结构文件不保证跨编译器、编译选项或机器可读，指针成员更不能作为跨进程可恢复的目标内容。需要长期保存或交换时，应约定版本、字段编码、长度与校验规则。文本格式也不必然低效或含糊，清楚的分隔、转义和数值精度同样能形成可靠格式。

# 14.8.1 保存结构的程序示例

保存程序要先明确是创建、覆盖还是追加。追加适合保留现有记录并在后面增加新项，但目标已有内容必须符合相应格式；选择a模式不会替程序验证旧记录。

### 以追加模式写入一条完整原生记录（完整标准C阅读程序）

命令行参数与文件写入不在C6范围。下面是完整标准C阅读程序，参数指定采用同一结构布局保存记录的目标文件。

```c
#include <stdio.h>
#include <stdlib.h>
struct Book { char title[8]; int copies; float price; };
int main(int argc, char *argv[])
{
    if (argc != 2) return EXIT_FAILURE;
    struct Book book = {"Elm", 2, 4.5f};
    FILE *file = fopen(argv[1], "ab");
    if (file == NULL) return EXIT_FAILURE;
    int failed = fwrite(&book, sizeof book, 1, file) != 1;
    if (fclose(file) != 0) failed = 1;
    return failed ? EXIT_FAILURE : EXIT_SUCCESS;
}
```

**教学预期（非本平台实测）**：成功时在现有文件末尾增加一条Elm、2、4.5记录；新文件则创建后写入。它不检查已有记录格式，也不能把任意文件自动转换成这种格式，短写或关闭失败均返回失败。

ab使本次完整Book记录写到文件末尾，目标不存在时尝试创建。程序检查fwrite是否完成一整项，并把fclose失败也视作保存失败，而不是写过一次就立刻宣称记录已落盘。

这个完整例子只追加，不读取或验证已有文件。需要读取旧内容再追加的更新流程序，应同时管理已读数量、容量、短记录、错误状态与方向切换，不能把任意外部字节直接当成可安全输出的字符数组和数值成员。原样记录格式的兼容前提应一直保留。

# 14.8.2 程序要点

结构文件传输需要把地址、单项大小、项数和实际结果对应起来。保存一条记录时，传的是对象地址，不是结构值；保存数组的一段时，还要选择正确起始元素与新增数量。

### 以追加模式写入一条完整原生记录（完整标准C阅读程序）

命令行参数与文件写入不在C6范围。下面是完整标准C阅读程序，参数指定采用同一结构布局保存记录的目标文件。

```c
#include <stdio.h>
#include <stdlib.h>
struct Book { char title[8]; int copies; float price; };
int main(int argc, char *argv[])
{
    if (argc != 2) return EXIT_FAILURE;
    struct Book book = {"Elm", 2, 4.5f};
    FILE *file = fopen(argv[1], "ab");
    if (file == NULL) return EXIT_FAILURE;
    int failed = fwrite(&book, sizeof book, 1, file) != 1;
    if (fclose(file) != 0) failed = 1;
    return failed ? EXIT_FAILURE : EXIT_SUCCESS;
}
```

**教学预期（非本平台实测）**：成功时在现有文件末尾增加一条Elm、2、4.5记录；新文件则创建后写入。它不检查已有记录格式，也不能把任意文件自动转换成这种格式，短写或关闭失败均返回失败。

`&book`指定数据起点，sizeof book指定一项大小，1指定项数；返回1才表示这一项已完整交付给流。追加模式负责把写入放在末尾，代码不需要先用错误的字段偏移猜测位置。

扩展为多条新增记录时，起始项应是第一条新记录，数量是新增项数，不能把旧记录再全部追加一遍。全部记录都要先满足初始化与有效性条件；只检查文件结束不够，还要处理读取错误或不完整尾记录。文件中的空间包括固定数组容量和实现填充，不能用书名实际长度推断下一条原生记录的位置。

# 14.9 链式结构

结构可以包含指向同类型其他对象的指针，由这些地址形成访问路径。直接内含一个完整自身实例会要求无穷展开，而保存一个指针只占该指针对象所需空间，因此能表示链或树节点。

### 结构保存下一节点地址，沿链接访问三项（完整C程序）

```c
#include <stdio.h>
struct Node { int value; struct Node *next; };
struct Node third = {3, 0};
struct Node second = {2, &third};
struct Node first = {1, &second};
int main(void)
{
    struct Node *current = &first;
    while (current != 0) {
        printf("%d\n", current->value);
        current = current->next;
    }
    return 0;
}
```

**输入**：无需输入。

**真实C6运行结果**：

```text
1
2
3
```

三个节点各自保存值与next指针，first连到second，second连到third，third的next为空。循环沿地址依次访问1、2、3，不要求节点按数组顺序相邻。本例使用持续存在的全局节点，没有动态分配或释放责任转移。

链式表示并不自动更快：链表顺序寻找仍需逐项访问，排序且较平衡的搜索树才可能减少查找层数；有序数组也可以二分查找。存在环、悬挂链接或错误目标时，普通“走到空指针”的循环也可能无法正确结束。数据组织、维护规则和使用算法共同决定效果，不能只因用了指针就宣称高效。

# 14.10 联合简介

联合让多个成员共享同一份存储，适合一个位置在不同状态下保存不同种类的值。结构让成员各自存在，联合则不能被当作同时保存所有独立字段的一条记录。

### 用标签记录联合当前保存的成员（完整标准C阅读程序）

union与值嵌套不在C6范围。下面是完整标准C阅读程序，只读取标签指示的当前成员。

```c
#include <stdio.h>
enum Kind { COUNT, PRICE };
union Value { int copies; double price; };
struct Entry { enum Kind kind; union Value value; };
void show(const struct Entry *entry)
{
    if (entry->kind == COUNT) printf("copies=%d\n", entry->value.copies);
    else if (entry->kind == PRICE) printf("price=%.1f\n", entry->value.price);
}
int main(void)
{
    struct Entry entry = {COUNT, {.copies = 3}};
    show(&entry);
    entry.value.price = 2.5;
    entry.kind = PRICE;
    show(&entry);
    return 0;
}
```

**教学预期（非本平台实测）**：先输出copies=3，再改为价格状态输出price=2.5。联合成员共享存储，后来写入price并没有保留一个独立的旧copies值，也不是把整数3自动转换成2.5。

entry先以COUNT状态解释copies，后写入price并把标签改成PRICE。两次show根据标签选择相应成员，不在写入价格后继续把旧数量当作仍保存着的独立值。标签属于程序维护的协议，联合本身不会自动检查标签是否与最近写入一致。

联合大小足以容纳最大成员，还可能因对齐与填充更大，不能普遍写成恰好等于某个成员大小。改写另一成员也不是进行通常的数值转换；若从不同成员重解释表示，涉及有效表示与可能陷阱等标准细节，不应靠某台机器上的偶然数值推导通用结论。本章采用标签与对应成员访问来保持含义清楚。

# 14.10.1 使用联合

联合对象可用点号选择成员，联合指针可用箭头选择目标成员，访问语法与结构相似。真正差别是共享存储以及当前值应按哪一种成员类型解释。

### 用标签记录联合当前保存的成员（完整标准C阅读程序）

union与值嵌套不在C6范围。下面是完整标准C阅读程序，只读取标签指示的当前成员。

```c
#include <stdio.h>
enum Kind { COUNT, PRICE };
union Value { int copies; double price; };
struct Entry { enum Kind kind; union Value value; };
void show(const struct Entry *entry)
{
    if (entry->kind == COUNT) printf("copies=%d\n", entry->value.copies);
    else if (entry->kind == PRICE) printf("price=%.1f\n", entry->value.price);
}
int main(void)
{
    struct Entry entry = {COUNT, {.copies = 3}};
    show(&entry);
    entry.value.price = 2.5;
    entry.kind = PRICE;
    show(&entry);
    return 0;
}
```

**教学预期（非本平台实测）**：先输出copies=3，再改为价格状态输出price=2.5。联合成员共享存储，后来写入price并没有保留一个独立的旧copies值，也不是把整数3自动转换成2.5。

初始化列表选定copies为3，show输出数量；随后写price为2.5并更新kind，show才输出价格。结构Entry把标签与联合放在一起，使读代码的人能看见如何选择当前解释方式。

添加一种新状态时，需要同时更新标签定义、初始化或写入路径，以及每个读取分支。不能只在联合中加一个字段，就期待旧show自动理解它。对只读接口使用const也不改变共享存储关系，它限制访问方式，而不是为各成员保存历史副本。

# 14.10.2 匿名联合（C11）

匿名联合省去外层选择联合成员名的一步，使内部字段可直接从包含它的结构访问。这只是名称与访问路径的简化，成员仍然共享存储。

### 匿名联合让成员可直接从外层选择（完整标准C阅读程序）

匿名联合不在C6范围。下面是完整C11标准C阅读程序，标签仍由程序维护。

```c
#include <stdio.h>
struct Entry {
    int kind;
    union { int copies; double price; };
};
int main(void)
{
    struct Entry entry = {0, {3}};
    if (entry.kind == 0) printf("%d\n", entry.copies);
    entry.price = 4.5;
    entry.kind = 1;
    if (entry.kind == 1) printf("%.1f\n", entry.price);
    return 0;
}
```

**教学预期（非本平台实测）**：先输出3，再把当前状态改为价格并输出4.5。entry.copies与entry.price共享匿名联合存储，匿名语法没有让两者变成同时独立保存的字段。

程序直接写entry.copies和entry.price，省去了像entry.value.price中的value。第一次状态为数量，第二次为价格；匿名写法并没有把二者变成两个独立并存的结构字段。

内层初值仍要对应联合当前选定成员，标签仍需同步维护。匿名成员进入外层可访问名称后，也要避免同名冲突。

# 14.11 枚举类型

枚举给相关整数常量起名字，并定义相应枚举类型，让状态、颜色或类别在程序中更易读。枚举符的名称在代码中代表数值，不是程序自动认识的外部输入字符串。

### 枚举符默认从0开始连续增加（完整C程序）

```c
#include <stdio.h>
enum Color { RED, GREEN, BLUE };
int main(void)
{
    enum Color selected = BLUE;
    printf("red=%d green=%d blue=%d\n", RED, GREEN, BLUE);
    switch (selected) {
        case BLUE: puts("selected=blue"); break;
        default: puts("selected=other"); break;
    }
    return 0;
}
```

**输入**：无需输入。

**真实C6运行结果**：

```text
red=0 green=1 blue=2
selected=blue
```

RED、GREEN、BLUE依次为0、1、2，selected保存BLUE对应值，switch使用具名常量判断。显示文字selected=blue来自程序自己写的字符串，不是printf自动把整数恢复成枚举符拼写。

本书的C11规则中，枚举符是int类型常量，枚举类型则与实现选定的适当整数类型兼容；不要固定其存储大小，也不要认为枚举变量自带运行时合法值检查。需要接受外部状态时，仍应显式验证业务范围或做文本映射。

# 14.11.1 enum常量

枚举符是具名整数常量，在C11中可用于需要相应整数常量表达式的场合，例如数组界限与switch的case。它们不是可以在后续语句中重新赋值的普通变量。

### 枚举符默认从0开始连续增加（完整C程序）

```c
#include <stdio.h>
enum Color { RED, GREEN, BLUE };
int main(void)
{
    enum Color selected = BLUE;
    printf("red=%d green=%d blue=%d\n", RED, GREEN, BLUE);
    switch (selected) {
        case BLUE: puts("selected=blue"); break;
        default: puts("selected=other"); break;
    }
    return 0;
}
```

**输入**：无需输入。

**真实C6运行结果**：

```text
red=0 green=1 blue=2
selected=blue
```

printf读出三个常量的数值，case BLUE使用值2作为匹配标签。enum Color是类型，selected是对象，BLUE是常量，三者不能混称为同一份变量。

常量名称进入普通标识符名称空间，同一作用域不能再用一个普通变量重占相同名字。C11还要求枚举常量值可由int表示；不能把超出范围的大整数直接写进去，再假定实现一定自动扩成更宽枚举常量。本课程保持教材的C11语境，不混入其他语言或不同标准版本的规则。

# 14.11.2 默认值

第一个没有显式值的枚举符默认为0；后续没有显式值的枚举符，取前一个值再加1。这里的默认规则发生在常量定义中，不会让枚举变量在每次使用时自动向下一个状态推进。

### 枚举符默认从0开始连续增加（完整C程序）

```c
#include <stdio.h>
enum Color { RED, GREEN, BLUE };
int main(void)
{
    enum Color selected = BLUE;
    printf("red=%d green=%d blue=%d\n", RED, GREEN, BLUE);
    switch (selected) {
        case BLUE: puts("selected=blue"); break;
        default: puts("selected=other"); break;
    }
    return 0;
}
```

**输入**：无需输入。

**真实C6运行结果**：

```text
red=0 green=1 blue=2
selected=blue
```

本例三个常量依次0、1、2，selected由显式初始化取得BLUE。selected没有自动依次经过RED与GREEN；需要状态转移时，必须由程序表达相应操作与合法转移条件。

若中途显式改变某个枚举符，后续默认值会从那个新值继续。因此需要连续数组索引时，应确认这组枚举值确实连续且在数组范围内，不能把任意枚举常量都拿来当安全下标。

# 14.11.3 赋值

枚举列表可以为某些常量显式指定整数常量表达式，其余项再按后续加1的规则决定。不同名称可以具有相同值，但这不会创造两个可用数值比较区分的状态。

### 显式枚举值改变后续默认起点，也允许重复值（完整C程序）

```c
#include <stdio.h>
enum Level { LOW = 1, MIDDLE = 4, NEXT, SAME = 4 };
int main(void)
{
    printf("%d %d %d %d\n", LOW, MIDDLE, NEXT, SAME);
    return 0;
}
```

**输入**：无需输入。

**真实C6运行结果**：

```text
1 4 5 4
```

LOW为1，MIDDLE为4，NEXT默认在4后取5，SAME也显式为4。因此MIDDLE与SAME比较相等，数值本身不能说明当初使用了哪一个拼写。

这里的等号给枚举常量规定值，不能在运行中再写MIDDLE等于另一个值。两个相同值的名称也不能在同一个switch中分别成为重复case标签；如果业务必须区分，设计时就需要不同数值或额外信息，而不是只换一个名字。

# 14.11.4 enum的用法

外部文本需要由程序明确映射为内部枚举值。scanf不会因为目标类型是enum就自动接受一个枚举符名字，输出函数也不会自动完成反向名称查找。

### 把输入文本显式映射为枚举值（完整C程序）

```c
#include <stdio.h>
#include <string.h>
enum Mode { MODE_RUN, MODE_STOP };
int main(void)
{
    char text[8];
    if (scanf("%7s", text) != 1) {
        puts("no input");
        return 0;
    }
    enum Mode mode;
    if (strcmp(text, "run") == 0) mode = MODE_RUN;
    else if (strcmp(text, "stop") == 0) mode = MODE_STOP;
    else {
        puts("unknown");
        return 0;
    }
    switch (mode) {
        case MODE_RUN: puts("running"); break;
        case MODE_STOP: puts("stopped"); break;
    }
    return 0;
}
```

**输入**：

```text
run
```

**真实C6运行结果**：

```text
running
```

run映射为MODE_RUN，stop映射为MODE_STOP，再由switch输出对应状态。unknown路径在使用mode之前返回，因此没有读未赋值枚举对象；空输入也单独报告。输入读取的是一项有宽度上限的词，不是完整命令行语法验证。

具名常量让分支目的清楚，但验证责任仍在程序。若用枚举值索引名称表，需要先保证值在表范围内；非连续枚举更适合显式映射。循环处理多项输入时，也要每轮重新设置查找结果，避免沿用上一轮“已找到”的状态。

# 14.11.5 共享名称空间

C把不同用途的标识符分到不同名称空间：结构、联合和枚举标记共享一类，普通标识符是一类，标签是一类，各个结构或联合的成员还有各自的成员名称空间。名称空间与作用域共同决定是否冲突。

### 标记、普通名字和各结构成员使用不同名称空间（完整C程序）

```c
#include <stdio.h>
struct status { int value; };
struct Other { int value; };
enum Color { COLOR_RED };
int status = 7;
int main(void)
{
    struct status a = {3};
    struct Other b = {5};
    printf("ordinary=%d a=%d b=%d enum=%d\n", status, a.value, b.value, COLOR_RED);
    return 0;
}
```

**输入**：无需输入。

**真实C6运行结果**：

```text
ordinary=7 a=3 b=5 enum=0
```

struct status的标记与普通变量status可以同拼写，a.value和b.value也分别属于两个结构类型。打印时写struct status来引用类型，单写status则访问普通整数对象，这两个角色没有混合。

同一作用域里不能再用enum status声明另一种同名标记，因为它与struct标记共享名称空间；枚举符与typedef名则进入普通标识符名称空间。名字可以合法共存，不等于这样命名总易读，实际接口仍宜选择能清楚表达含义的名称。

# 14.12 typedef简介

typedef给已有类型建立别名，不是预处理器的文本替换，也不把同一种基础类型变成新的不相容类型。它适合简化结构、指针及复杂声明，同时保留完整类型的组合关系。

### typedef重复引用同一类型，指针别名仍是一整个类型（完整C程序）

```c
#include <stdio.h>
typedef struct { int x; int y; } Point;
typedef int *IntLink;
int main(void)
{
    Point first = {2, 3};
    Point second = {5, 8};
    int value = 4;
    IntLink const fixed = &value;
    *fixed = 6;
    printf("%d %d %d\n", first.x, second.y, value);
    return 0;
}
```

**输入**：无需输入。

**真实C6运行结果**：

```text
2 8 6
```

Point在定义处命名同一份无标记结构类型，first与second随后都引用它；不是每次写Point就重新定义一份匿名结构。IntLink包含完整的int指针类型，所以给这个别名加const限定的是指针本身，仍可经fixed修改value为6。

两次独立写出相同成员的无标记结构定义，在同一翻译单元仍会建立不同类型，不能把typedef展开成两份独立结构定义后声称完全等价。这可对照[C11草案N1570的6.7.2.3](https://www.open-std.org/jtc1/sc22/wg14/www/docs/n1570.pdf)。宏替换也不同：把char星号简单替换进一条多变量声明，并不能让每个变量都自动成为指针。

标准库的size_t等名字让实现选择符合要求的具体类型，使用者依接口约定编程，不应猜测它总等于某种基本类型。size_t是无符号整数类型，time_t则是能表示时间的实类型，不要求必定为整数；类型别名不是把所有库类型都统一成int。

# 14.13 其他复杂的声明

复杂声明应从被声明的名字出发，按括号、数组与函数后缀、指针层次逐步解释。声明中的结合关系决定类型，不是把出现的星号和方括号数量加起来就能辨认。

### 数组指针、指针数组和二级指针各有不同层次（完整标准C阅读程序）

指向数组、指针数组与二级指针不在C6范围。下面是完整标准C阅读程序，保留各自真实类型。

```c
#include <stdio.h>
int main(void)
{
    int row[3] = {1, 2, 3};
    int (*whole)[3] = &row;
    int *items[2] = {row, row + 2};
    int **link = &items[0];
    printf("%d %d %d\n", (*whole)[1], *items[1], **link);
    return 0;
}
```

**教学预期（非本平台实测）**：whole指向整行，(*whole)[1]得到2；items[1]指向第三项，读到3；link指向items[0]这个指针对象，两次解引用得到1。输出2 3 1。

whole先被括号与星号结合，是指向三项int数组的指针；items先与数组后缀结合，是两个int指针组成的数组；link则指向一个int指针对象。三条访问依次得到2、3、1，但对象层次并不相同。

同理，`int *function(int)`声明返回int指针的函数，`int (*selected)(int)`声明指向函数的指针。数组不能直接以内含普通函数对象的形式声明，却可以保存函数指针；函数也不能直接返回数组或函数类型，但可以返回适当指针。类型过长时可用typedef分步命名，仍要保留每一步真实的指针、数组与函数关系。

# 14.14 函数和指针

函数指针让调用者把“使用哪种操作”传给另一函数，后者再按统一接口调用。函数名在相应表达式中可转换为函数指针，它不是一个可重新赋值的指针变量，也不必被理解成可按字节随意计算的机器代码地址。

### 把所选操作作为函数指针传入（完整标准C阅读程序）

函数指针及其数组不在C6范围。下面是完整标准C阅读程序，两份回调具有同一函数类型。

```c
#include <stdio.h>
typedef int (*Operation)(int);
int twice(int value)
{
    return value * 2;
}
int increment(int value)
{
    return value + 1;
}
int apply(Operation operation, int value)
{
    return operation(value);
}
int main(void)
{
    Operation operations[2] = {twice, increment};
    printf("%d %d\n", apply(operations[0], 4), (*operations[1])(4));
    return 0;
}
```

**教学预期（非本平台实测）**：apply调用twice处理4得到8，另一种解引用调用形式调用increment处理4得到5，输出8 5。传入的是函数选择，不是先调用函数后传入计算结果。

twice与increment都接受int并返回int，符合Operation类型。apply调用所传操作处理4得到8，第二种括号解引用形式调用increment得到5；`operation(value)`与`(*operation)(value)`都可用于相应函数指针调用。

传twice选择函数，传`twice(4)`则先调用并传整数结果，两者不是同一种实参。函数返回类型和参数类型必须与指针兼容，不能靠强制转换让不匹配调用变得正确，也不能调用空函数指针。Operation数组保存两个函数指针，并非保存两个函数对象。

比较回调、菜单选择和其他策略接口都可以采用这种方式，但需要各自匹配的函数类型；本例的int到int接口不能直接当作qsort比较函数。C的对象指针与函数指针也有不同规则，不要为了打印或存储就假定函数指针可移植地转换成void指针。

# 14.15 关键概念

数据形式与配套函数共同决定一份程序是否易于组织。结构聚合相关字段，函数接口说明如何读取、修改或产生记录；指针成员则要求进一步明确目标寿命和所有权。

### 通过结构指针修改原记录，再只读计算（完整C程序）

```c
#include <stdio.h>
struct Stock { int copies; float price; };
void add_copy(struct Stock *stock)
{
    ++stock->copies;
}
float cost(const struct Stock *stock)
{
    return stock->copies * stock->price;
}
int main(void)
{
    struct Stock stock = {2, 5.0f};
    add_copy(&stock);
    printf("copies=%d cost=%.2f\n", stock.copies, cost(&stock));
    return 0;
}
```

**输入**：无需输入。

**真实C6运行结果**：

```text
copies=3 cost=15.00
```

stock把数量和价格放在一起，add_copy表达一项修改，cost提供只读计算。增加无关字段时，调用者仍可围绕一条记录传递信息，但所有依赖新字段的初始化和处理路径都需要同步检查。

联合通过共享存储表示多种状态，枚举为状态值命名，typedef简化类型表达，函数指针把操作选择纳入接口。它们解决的分别是不同问题，不能用一个关键字自动获得深复制、合法值验证、资源释放或更高性能。

# 14.16 本章小结

本章应能从一份记录定义看清成员类型，从访问表达式看清对象层次，从函数签名判断传值还是传地址。结构数组、嵌套、指针与文件表示都是在这些规则上继续组合。

### 每个数组元素是一条完整结构记录（完整C程序）

```c
#include <stdio.h>
struct Book { char title[8]; int copies; float price; };
int main(void)
{
    struct Book books[2] = {{"Elm", 2, 4.5f}, {"Oak", 1, 3.0f}};
    float total = 0.0f;
    for (int i = 0; i < 2; ++i) {
        printf("%s copies=%d\n", books[i].title, books[i].copies);
        total += books[i].copies * books[i].price;
    }
    printf("total=%.2f last=%c\n", total, books[1].title[2]);
    return 0;
}
```

**输入**：无需输入。

**真实C6运行结果**：

```text
Elm copies=2
Oak copies=1
total=12.00 last=k
```

这份完整程序先选数组元素，再选该条记录的成员，最后按有效字段计算金额并读取一个字符。记录边界与成员边界都清楚，数组名、结构对象和结构指针没有混称为一种地址。

结构复制包含内含数组的值，却不会自动复制指针目标；结构文件原样保存依赖对象表示。联合成员共享存储，枚举符是具名整数常量，typedef引用同一类型，函数指针以兼容签名选择操作。

