    struct { char first[8]; char last[8]; };
};
int main(void)
{
    struct Person person = {7, {"Ana", "Li"}};
    printf("%d %s %s\n", person.id, person.first, person.last);
    return 0;
}

#include <stdio.h>
struct Stock { int copies; float price; };
float cost_all(const struct Stock *stocks, int count)
{
    float total = 0.0f;
    for (int i = 0; i < count; ++i)
        total += stocks[i].copies * stocks[i].price;
    return total;
}
int main(void)
{
    struct Stock stocks[2] = {{2, 4.5f}, {1, 3.0f}};
    int count;
    if (scanf("%d", &count) != 1 || count < 0 || count > 2) {
        puts("invalid count");
        return 0;
    }
    printf("%.2f\n", cost_all(stocks, count));
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
struct Book { char title[8]; int copies; float price; };
int main(void)
{
    struct Book book = {"Elm", 2, 4.5f};
    struct Book restored;
    FILE *file = tmpfile();
    if (file == NULL) return EXIT_FAILURE;
    int failed = fwrite(&book, sizeof book, 1, file) != 1;
    if (!failed && fseek(file, 0L, SEEK_SET) != 0) failed = 1;
    if (!failed && fread(&restored, sizeof restored, 1, file) != 1) failed = 1;
    if (!failed && printf("%s %d %.2f\n",
                          restored.title, restored.copies, restored.price) < 0) failed = 1;
    if (fclose(file) != 0) failed = 1;
    return failed ? EXIT_FAILURE : EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
struct Book { char title[8]; int copies; float price; };
int main(int argc, char *argv[])
{
    if (argc != 2) return EXIT_FAILURE;
    struct Book book = {"Elm", 2, 4.5f};
    FILE *file = fopen(argv[1], "ab");
    if (file == NULL) return EXIT_FAILURE;
    int failed = fwrite(&book, sizeof book, 1, file) != 1;
    if (fclose(file) != 0) failed = 1;
    return failed ? EXIT_FAILURE : EXIT_SUCCESS;
}

#include <stdio.h>
struct Node { int value; struct Node *next; };
struct Node third = {3, 0};
struct Node second = {2, &third};
struct Node first = {1, &second};
int main(void)
{
    struct Node *current = &first;
    while (current != 0) {
        printf("%d\n", current->value);
        current = current->next;
    }
    return 0;
}

#include <stdio.h>
enum Kind { COUNT, PRICE };
union Value { int copies; double price; };
struct Entry { enum Kind kind; union Value value; };
void show(const struct Entry *entry)
{
    if (entry->kind == COUNT) printf("copies=%d\n", entry->value.copies);
    else if (entry->kind == PRICE) printf("price=%.1f\n", entry->value.price);
}
int main(void)
{
    struct Entry entry = {COUNT, {.copies = 3}};
    show(&entry);
    entry.value.price = 2.5;
    entry.kind = PRICE;
    show(&entry);
    return 0;
}

#include <stdio.h>
struct Entry {
    int kind;
    union { int copies; double price; };
};
int main(void)
{
    struct Entry entry = {0, {3}};
    if (entry.kind == 0) printf("%d\n", entry.copies);
    entry.price = 4.5;
    entry.kind = 1;
    if (entry.kind == 1) printf("%.1f\n", entry.price);
    return 0;
}

#include <stdio.h>
enum Color { RED, GREEN, BLUE };
int main(void)
{
    enum Color selected = BLUE;
    printf("red=%d green=%d blue=%d\n", RED, GREEN, BLUE);
    switch (selected) {
        case BLUE: puts("selected=blue"); break;
        default: puts("selected=other"); break;
    }
    return 0;
}

#include <stdio.h>
enum Level { LOW = 1, MIDDLE = 4, NEXT, SAME = 4 };
int main(void)
{
    printf("%d %d %d %d\n", LOW, MIDDLE, NEXT, SAME);
    return 0;
}

#include <stdio.h>
#include <string.h>
enum Mode { MODE_RUN, MODE_STOP };
int main(void)
{
    char text[8];
    if (scanf("%7s", text) != 1) {
        puts("no input");
        return 0;
    }
    enum Mode mode;
    if (strcmp(text, "run") == 0) mode = MODE_RUN;
    else if (strcmp(text, "stop") == 0) mode = MODE_STOP;
    else {
        puts("unknown");
        return 0;
    }
    switch (mode) {
        case MODE_RUN: puts("running"); break;
        case MODE_STOP: puts("stopped"); break;
    }
    return 0;
}

#include <stdio.h>
struct status { int value; };
struct Other { int value; };
enum Color { COLOR_RED };
int status = 7;
int main(void)
{
    struct status a = {3};
    struct Other b = {5};
    printf("ordinary=%d a=%d b=%d enum=%d\n", status, a.value, b.value, COLOR_RED);
    return 0;
}

#include <stdio.h>
typedef struct { int x; int y; } Point;
typedef int *IntLink;
int main(void)
{
    Point first = {2, 3};
    Point second = {5, 8};
    int value = 4;
    IntLink const fixed = &value;
    *fixed = 6;
    printf("%d %d %d\n", first.x, second.y, value);
    return 0;
}

#include <stdio.h>
int main(void)
{
    int row[3] = {1, 2, 3};
    int (*whole)[3] = &row;
    int *items[2] = {row, row + 2};
    int **link = &items[0];
    printf("%d %d %d\n", (*whole)[1], *items[1], **link);
    return 0;
}

#include <stdio.h>
typedef int (*Operation)(int);
int twice(int value)
{
    return value * 2;
}
int increment(int value)
{
    return value + 1;
}
int apply(Operation operation, int value)
{
    return operation(value);
}
int main(void)
{
    Operation operations[2] = {twice, increment};
    printf("%d %d\n", apply(operations[0], 4), (*operations[1])(4));
    return 0;
}

#include <stdio.h>
struct Stock { int copies; float price; };
void add_copy(struct Stock *stock)
{
    ++stock->copies;
}
float cost(const struct Stock *stock)
{
    return stock->copies * stock->price;
}
int main(void)
{
    struct Stock stock = {2, 5.0f};
    add_copy(&stock);
    printf("copies=%d cost=%.2f\n", stock.copies, cost(&stock));
    return 0;
}

#include <stdio.h>
struct Point { int x; int y; };
struct Point moved(struct Point value)
{
    value.x += 2;
    return value;
}
int main(void)
{
    struct Point original = {1, 3};
    struct Point copy = moved(original);
    copy.y = 8;
    printf("original=%d,%d copy=%d,%d\n",
           original.x, original.y, copy.x, copy.y);
    return 0;
}

#include <stdio.h>
struct Text { char owned[8]; char *borrowed; };
int main(void)
{
    char shared[8] = "oak";
    struct Text original = {"elm", shared};
    struct Text copy = original;
    copy.owned[0] = 'E';
    copy.borrowed[0] = 'O';
    printf("original=%s copy=%s shared=%s same=%d\n",
           original.owned, copy.owned, shared, original.borrowed == copy.borrowed);
    return 0;
}

#include <stdio.h>
struct Text { char owned[8]; const char *borrowed; };
int main(void)
{
    struct Text text = {"elm", "oak"};
    printf("before=%s/%s\n", text.owned, text.borrowed);
    text.owned[0] = 'E';
    text.borrowed = text.owned;
    printf("after=%s/%s\n", text.owned, text.borrowed);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
struct Name { char *first; char *last; };
int main(void)
{
    struct Name person = {NULL, NULL};
    person.first = malloc(sizeof "Ana");
    if (person.first == NULL) return EXIT_FAILURE;
    person.last = malloc(sizeof "Li");
    if (person.last == NULL) {
        free(person.first);
        return EXIT_FAILURE;
    }
    strcpy(person.first, "Ana");
    strcpy(person.last, "Li");
    int failed = printf("%s %s\n", person.first, person.last) < 0;
    free(person.first);
    free(person.last);
    return failed ? EXIT_FAILURE : EXIT_SUCCESS;
}

#include <stdio.h>

struct Book {
    char title[24];
    char author[16];
    float price;
    int copies;
};

int main(void)
{
    struct Book book = { // 初始化时，初值按成员的声明顺序对应。
        "C Steps",
        "Lin",
        12.50f,
        2
    };
    struct Book draft = {"Draft"}; // 部分初始化：其余成员也初始化；作者为空串，价格和数量为零。
    float total = book.price * book.copies;

    printf("initial: %s | %s | price=%.2f | copies=%d | total=%.2f\n",
           book.title, book.author, book.price, book.copies, total);
    printf("partial: %s | author=<%s> | price=%.2f | copies=%d\n",
           draft.title, draft.author, draft.price, draft.copies);

    book.price = 10.00f;
    book.copies = book.copies + 1;
    total = book.price * book.copies;
    printf("updated: %s | %s | price=%.2f | copies=%d | total=%.2f\n",
           book.title, book.author, book.price, book.copies, total);
    return 0;
}

#include <stdio.h>
struct Stock { int copies; float price; };
int main(void)
{
    int requested = 3;
    struct Stock item = {requested, 5.00f}; // 标准C允许自动对象的初值读取变量；当前C6暂不支持。
    printf("%.2f\n", item.copies * item.price);
    return 0;
}

#include <stdio.h>
struct Stock { char code[4]; int copies; };
int main(void)
{
    struct Stock stocks[2] = {{"elm", 2}, {"oak", 3}};
    struct Stock *selected = stocks;
    printf("%s:%d\n", selected->code, selected->copies);
    ++selected;
    printf("%s:%d\n", selected->code, selected->copies);
    return 0;
}

