#include <stdio.h>
#include <math.h>
struct polar {
    double magnitude;
    double degrees;
};
struct polar convert(double x, double y)
{
    struct polar result;
    result.magnitude = hypot(x, y);
    /* 原点没有唯一方向，这里为显示约定为0。 */
    result.degrees = result.magnitude == 0.0
        ? 0.0 : atan2(y, x) * (180.0 / (4.0 * atan(1.0)));
    return result;
}
void report(double x, double y)
{
    struct polar result = convert(x, y);
    printf("length=%.2f angle=%.2f\n", result.magnitude, result.degrees);
}
int main(void)
{
    report(4.0, 3.0);
    report(-4.0, -3.0);
    report(0.0, 3.0);
    report(0.0, 0.0);
    return 0;
}

