int compare_int(const void *left, const void *right)
{
    const int *a = left;
    const int *b = right;
    return (*a > *b) - (*a < *b);
}
int main(void)
{
    int values[] = {INT_MAX, 4, INT_MIN, 0, -2, 4};
    size_t count = sizeof values / sizeof values[0];
    qsort(values, count, sizeof values[0], compare_int);
    for (size_t i = 0; i < count; ++i)
        printf("%d\n", values[i]);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
struct name {
    char first[16];
    char last[16];
};
int compare_name(const void *left, const void *right)
{
    const struct name *a = left;
    const struct name *b = right;
    int order = strcmp(a->last, b->last);
    return order != 0 ? order : strcmp(a->first, b->first);
}
int main(void)
{
    struct name people[] = {{"Zoe", "Wu"}, {"Bo", "Lin"}, {"Ada", "Lin"}};
    size_t count = sizeof people / sizeof people[0];
    qsort(people, count, sizeof people[0], compare_name);
    for (size_t i = 0; i < count; ++i)
        printf("%s %s\n", people[i].first, people[i].last);
    return 0;
}

#include <stdio.h>
#include <assert.h>
int main(void)
{
    double x = 3.0;
    double y = 5.0;
    double difference = x * x - y * y;
    assert(difference >= 0.0);
    puts("reached");
    return 0;
}

#include <stdio.h>
#include <limits.h>
_Static_assert(CHAR_BIT == 16, "This example requires a 16-bit char");
int main(void)
{
    puts("char has 16 bits");
    return 0;
}

#include <stdio.h>
#include <string.h>
void show(const int values[], size_t count)
{
    for (size_t i = 0; i < count; ++i)
        printf("%s%d", i == 0 ? "" : " ", values[i]);
    putchar('\n');
}
int main(void)
{
    int values[6] = {1, 2, 3, 4, 5, 6};
    int copy[6];
    memcpy(copy, values, sizeof values);
    show(copy, 6);
    /* 源和目标在同一数组内重叠。 */
    memmove(values + 2, values, 4 * sizeof values[0]);
    show(values, 6);
    double original = 2.5;
    unsigned char representation[sizeof original];
    double restored;
    memcpy(representation, &original, sizeof original);
    memcpy(&restored, representation, sizeof restored);
    printf("restored=%.1f\n", restored);
    return 0;
}

#include <stdio.h>
#include <stdarg.h>
void report_sum(int count, ...)
{
    va_list current;
    va_list saved;
    va_start(current, count);
    va_copy(saved, current);
    double first = 0.0;
    double second = 0.0;
    for (int i = 0; i < count; ++i)
        first += va_arg(current, double);
    va_end(current);
    for (int i = 0; i < count; ++i)
        second += va_arg(saved, double);
    va_end(saved);
    printf("first=%.2f second=%.2f\n", first, second);
}
int main(void)
{
    report_sum(2, 1.25f, 2.5);
    report_sum(3, 1.0, 2.0, 3.0);
    report_sum(0);
    return 0;
}

#include <stdio.h>
#define SQUARE(x) ((x) * (x))
int main(void)
{
    int x = 5;
    int answer = SQUARE(++x);
    printf("answer=%d x=%d\n", answer, x);
    return 0;
}

