int main(void)
{
    List movies;
    ListInit(&movies);
    Item first = {"Moss", 8};
    Item second = {"River", 9};
    Item third = {"Dune", 7};
    if (!ListPush(&first, &movies) || !ListPush(&second, &movies) ||
        !ListPush(&third, &movies)) {
        ListClear(&movies);
        return EXIT_FAILURE;
    }
    int extra = ListPush(&first, &movies);
