    size_t count;
} List;
void ListInit(List *list);
bool ListIsEmpty(const List *list);
bool ListIsFull(const List *list);
size_t ListCount(const List *list);
/* 成功追加一个值副本；失败保持原列表。item须为合法的完整记录。 */
bool ListPush(const Item *item, List *list);
/* visit不得删除或修改正在遍历的列表。 */
void ListVisit(const List *list, void (*visit)(const Item *));
void ListClear(List *list);
#endif
```

**list.c**

```c
#include <stdlib.h>
#include "list.h"
struct list_node {
    Item item;
    ListNode *next;
};
void ListInit(List *list)
{
    list->head = NULL;
    list->tail = NULL;
    list->count = 0;
}
bool ListIsEmpty(const List *list)
{
    return list->count == 0;
}
bool ListIsFull(const List *list)
{
    return list->count == LIST_CAPACITY;
}
size_t ListCount(const List *list)
{
    return list->count;
}
bool ListPush(const Item *item, List *list)
{
    if (ListIsFull(list))
        return false;
    ListNode *node = malloc(sizeof *node);
    if (node == NULL)
        return false;
    node->item = *item;
    node->next = NULL;
    /* 新节点完整就绪后才接入；失败路径不会破坏原列表。 */
    if (list->tail == NULL)
        list->head = node;
    else
        list->tail->next = node;
    list->tail = node;
    ++list->count;
    return true;
}
void ListVisit(const List *list, void (*visit)(const Item *))
{
    const ListNode *node = list->head;
    while (node != NULL) {
        visit(&node->item);
        node = node->next;
    }
}
void ListClear(List *list)
{
    ListNode *node = list->head;
    while (node != NULL) {
        ListNode *next = node->next;
        free(node);
        node = next;
    }
    list->head = NULL;
    list->tail = NULL;
    list->count = 0;
}
```

**教学预期（非本平台实测）**：前三项分配成功时，第四次追加因容量3返回0，count=3；回调依次显示Moss:8、River:9、Dune:7。清空两次后empty=1 count=0。任何分配失败都先清理已建列表，再报告失败终止。

列表库把具体节点处理收在实现中，业务方只用约定操作。这种组织方式能让测试与修改集中在边界：如果替换表示，就同时核对顺序、容量、复制和清理语义，而不只比较某次输出文本。

本书附录中的补充阅读和库汇总可供按需查询，作为参考资料使用。它们不额外展开成新的教学章，也不因阅读参考就宣称平台已经提供完整宿主扩展库或其他语言执行能力。

# 17.9 关键概念

类型不仅是存储布局，也包括允许的操作与状态约束。ADT先说明这些可观察规则，接口把规则表达成调用方式，实现则把规则落实到数组、节点、计数与连接更新上。

### 队首出队、队尾入队，单项边界恢复两个入口（完整标准C阅读程序）

用户头、多文件链接与动态分配不在C6范围。三个文件保留完整队列接口、实现和驱动。

**main.c**

```c
#include <stdio.h>
#include <stdlib.h>
#include "queue.h"
int main(void)
{
    Queue queue;
    QueueInit(&queue);
    if (!QueuePush(40, &queue) || !QueuePush(20, &queue) ||
        !QueuePush(55, &queue)) {
        QueueClear(&queue);
        return EXIT_FAILURE;
    }
    int extra = QueuePush(73, &queue);
    printf("extra=%d count=%d\n", extra, QueueCount(&queue));
    Item value;
    while (QueuePop(&value, &queue))
        printf("removed=%d\n", value);
    value = 777;
    int obtained = QueuePop(&value, &queue);
    printf("empty-pop=%d unchanged=%d\n", obtained, value);
    if (!QueuePush(7, &queue)) {
        QueueClear(&queue);
        return EXIT_FAILURE;
    }
    if (QueuePop(&value, &queue))
        printf("reused=%d\n", value);
    QueueClear(&queue);
    QueueClear(&queue);
    printf("count=%d\n", QueueCount(&queue));
    return 0;
}
```

**queue.h**

```c
#ifndef COURSE_INT_QUEUE_H
#define COURSE_INT_QUEUE_H
#include <stdbool.h>
#define QUEUE_CAPACITY 3
typedef int Item;
typedef struct queue_node QueueNode;
typedef struct {
    QueueNode *front;
    QueueNode *rear;
    int count;
} Queue;
void QueueInit(Queue *queue);
bool QueueIsEmpty(const Queue *queue);
bool QueueIsFull(const Queue *queue);
int QueueCount(const Queue *queue);
/* 满或分配失败返回false，原队列不变。 */
bool QueuePush(Item item, Queue *queue);
/* 空时返回false，*item不变；输出对象须有效且不与队列内部存储重叠。 */
bool QueuePop(Item *item, Queue *queue);
void QueueClear(Queue *queue);
#endif
```

**queue.c**

```c
#include <stdlib.h>
#include "queue.h"
struct queue_node {
    Item item;
    QueueNode *next;
};
void QueueInit(Queue *queue)
{
    queue->front = NULL;
    queue->rear = NULL;
    queue->count = 0;
}
bool QueueIsEmpty(const Queue *queue)
{
    return queue->count == 0;
}
bool QueueIsFull(const Queue *queue)
{
    return queue->count == QUEUE_CAPACITY;
}
int QueueCount(const Queue *queue)
{
    return queue->count;
}
bool QueuePush(Item item, Queue *queue)
{
    if (QueueIsFull(queue))
        return false;
    QueueNode *node = malloc(sizeof *node);
    if (node == NULL)
        return false;
    node->item = item;
    node->next = NULL;
    if (queue->rear == NULL)
        queue->front = node;
    else
        queue->rear->next = node;
    queue->rear = node;
    ++queue->count;
    return true;
}
bool QueuePop(Item *item, Queue *queue)
{
    if (QueueIsEmpty(queue))
        return false;
    QueueNode *old = queue->front;
    *item = old->item;
    queue->front = old->next;
    --queue->count;
    /* 删除最后一项后，rear也必须回到空状态。 */
    if (queue->count == 0)
        queue->rear = NULL;
    free(old);
    return true;
}
void QueueClear(Queue *queue)
{
    Item unused;
    while (QueuePop(&unused, queue)) {
    }
}
```

**教学预期（非本平台实测）**：三个节点分配成功时，满队列追加返回0、数量仍3；依次取40、20、55，空时输出变量777不变。空队列再次加入7可正常取出，清空两次后count=0。

FIFO和失败不改原状态属于接口合同；首尾指针、分配与释放属于实现细节。实现内部各操作共享不变量，某个出队函数遗漏最后节点的尾入口恢复，会破坏以后入队，即使眼前输出看似正确。

接口隐藏有助于减少这种误用，但C的别名和公开对象仍要求纪律。`const`不是全图冻结，类型别名不是自动深复制，初始化也不是垃圾回收。

# 17.10 本章小结

列表、队列和树把基础结构、指针、函数与资源管理组合成完整的数据表示方案。表示选择应考虑操作：数组适合直接定位，链表适合已知位置附近调整，平衡搜索树适合维持有序查找，各自仍有成本与边界。

### 环形数组用首下标与计数区别空和满（完整C程序）

```c
#include <stdio.h>
#define CAPACITY 3
struct queue {
    int front;
    int count;
};
void initialize(struct queue *queue)
{
    queue->front = 0;
    queue->count = 0;
}
int enqueue(int value, int data[], struct queue *queue)
{
    if (queue->count == CAPACITY)
        return 0;
    int index = (queue->front + queue->count) % CAPACITY;
    data[index] = value;
    ++queue->count;
    return 1;
}
int dequeue(int *value, const int data[], struct queue *queue)
{
    if (queue->count == 0)
        return 0;
    *value = data[queue->front];
    queue->front = (queue->front + 1) % CAPACITY;
    --queue->count;
    return 1;
}
int main(void)
{
    int data[CAPACITY];
    struct queue queue;
    initialize(&queue);
    int value = 777;
    int obtained = dequeue(&value, data, &queue);
    printf("empty-pop=%d unchanged=%d\n", obtained, value);
    enqueue(10, data, &queue);
    enqueue(20, data, &queue);
    enqueue(30, data, &queue);
    int extra = enqueue(40, data, &queue);
    printf("extra=%d full-count=%d\n", extra, queue.count);
    if (dequeue(&value, data, &queue))
        printf("first=%d\n", value);
    enqueue(40, data, &queue);
    while (dequeue(&value, data, &queue))
        printf("next=%d\n", value);
    printf("empty=%d count=%d\n", queue.count == 0, queue.count);
    enqueue(50, data, &queue);
    if (dequeue(&value, data, &queue))
        printf("reused=%d\n", value);
    return 0;
}
```

**输入**：无需输入。

**真实C6运行结果**：

```text
empty-pop=0 unchanged=777
extra=0 full-count=3
first=10
next=20
next=30
next=40
empty=1 count=0
reused=50
```

同一个队列抽象在这里用环形数组实现，靠计数和回绕保持FIFO；换成节点实现后，调用方仍应看到一致的空、满、成功和失败含义。能否替换要看这些合同，而不是内部长得是否一样。

完成一个方案时，除了正常路径，还要验证空集合、满容量、重复键、缺失查询、最后一项删除、失败后状态与重复清理。

