#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <ctype.h>
#include <limits.h>
#include "interactive_api.h"

static int read_line(char *text, int capacity) {
    if (capacity < 2) return -1;
    if (fgets(text, capacity, stdin) == NULL) return ferror(stdin) ? -1 : 0;
    char *end = strchr(text, '\n');
    if (end != NULL) { *end = '\0'; return 1; }
    int ch = getchar();
    if (ch == '\n') return 1;
    if (ch == EOF) return ferror(stdin) ? -1 : 1;
    while (ch != '\n' && ch != EOF) ch = getchar();
    return -1;
}

static int read_integer(int *output) {
    char text[64];
    int status = read_line(text, 64);
    if (status != 1) return status;
    char *end;
    errno = 0;
    long value = strtol(text, &end, 10);
    if (end == text || errno == ERANGE) return -1;
    while (isspace((unsigned char)*end)) end++;
    if (*end != '\0' || value < INT_MIN || value > INT_MAX) return -1;
    *output = (int)value;
    return 1;
}

int main(void) {
    Queue queue;
    QInit(&queue);
    int failed = 0;
    while (1) {
        int choice = getchar();
        if (choice == EOF) break;
        if (choice != '\n') {
            int tail;
            while ((tail = getchar()) != '\n' && tail != EOF) {}
        }
        if (choice == 'q') break;
        if (choice == 'a') {
            Item value = 0;
            int status = read_integer(&value);
            if (status == 0) break;
            if (status < 0) {
                if (ferror(stdin)) { failed = 1; break; }
                puts("INVALID INTEGER");
                continue;
            }
            puts(QPush(value, &queue) ? "ADDED" : "ADD FAILED");
        } else if (choice == 'd') {
            Item value = 0;
            if (QPop(&value, &queue)) printf("REMOVED %d\n", value);
            else puts("EMPTY");
        } else { puts("INVALID MENU"); continue; }
        printf("count=%d\n", QCount(&queue));
    }
    if (ferror(stdin)) failed = 1;
    QClear(&queue);
    return failed;
}

