        values[i] = values[i + 1];
    --count;
    printf("array-delete:");
    for (int i = 0; i < count; ++i)
        printf(" %d", values[i]);
    putchar('\n');
    added.next = first.next;
    first.next = &added;
    printf("list-insert:");
    show(&first);
    added.next = middle.next;
    printf("list-delete:");
    show(&first);
    return 0;
}

